#' Build the header logo tag from the embedded base64 payload
#'
#' Performs no disk read and no network request at runtime, which is what keeps
#' app.R a single standalone file.
#'
#' @return shiny.tag — an <img> element with a data URI src
icarda_logo_tag <- function() {
  tags$img(
    src    = paste0("data:image/png;base64,", ICARDA_LOGO_B64),
    height = "64px",
    alt    = "ICARDA",
    style  = "margin-right: 12px; vertical-align: middle;"
  )
}

#' Derive family from SELHIS
#'
#' Extracts the first two hyphen-separated segments of a SELHIS string as the
#' family grouping. Vectorized to work with character vectors.
#'
#' @param selhis character vector
#' @return character vector — family grouping
derive_family <- function(selhis) {
  vapply(selhis, function(s) {
    segments <- strsplit(s, "-", fixed = TRUE)[[1]]
    if (length(segments) >= 2) {
      paste(segments[1:2], collapse = "-")
    } else {
      s
    }
  }, character(1), USE.NAMES = FALSE)
}

#' Check if DiGGer package is available
check_digger_available <- function() {
  requireNamespace("DiGGer", quietly = TRUE)
}

# -----------------------------------------------------------------------------
# 4. Scenario Arithmetic (pure — mirrors the Excel Scenario Builder)
# -----------------------------------------------------------------------------

#' Coerce one scenario input to a length-1 numeric
#'
#' Shiny numeric inputs arrive as NULL while a control is still empty and as
#' character when a value is typed into a text box, so every formula below goes
#' through this helper rather than trusting the raw parameter.
#'
#' @param x numeric|character|NULL
#' @return numeric — NA_real_ when the value is absent or not parseable
scenario_num <- function(x) {
  if (is.null(x) || length(x) == 0) return(NA_real_)
  suppressWarnings(as.numeric(x[[1]]))
}

#' Format a scenario number for display inside the block size summary
#'
#' Whole values print with no decimal point ("200", never "200.0"); fractional
#' values keep up to six decimals with trailing zeros trimmed. Scientific
#' notation is suppressed so large plot counts stay readable (Req 6.10).
#'
#' @param x numeric
#' @return character
format_scenario_number <- function(x) {
  if (length(x) != 1 || !is.finite(x)) return(as.character(x))
  if (isTRUE(all.equal(x, round(x)))) {
    return(format(round(x), scientific = FALSE, trim = TRUE))
  }
  out <- formatC(x, format = "f", digits = 6, big.mark = "")
  out <- sub("0+$", "", out)
  sub("\\.$", "", out)
}

#' Compute all Scenario Builder derived values
#'
#' The single source of truth for every number the App displays or emits. Pure
#' arithmetic: no Shiny, DiGGer or ggplot2 dependency, and no input rejection.
#'
#' @param params list(locations, test_entries, check_entries, cross_entries,
#'                    prep_per_loc, blocks, field_rows, field_cols,
#'                    block_rows, block_cols)
#' @return list(common_per_loc, unrep_per_loc, pure_test, required_plots,
#'              total_entries_per_loc, replication_ratio, connectivity_ratio,
#'              field_plots, block_plots, block_size_summary)
#' @details Cell references are the Scenario Builder workbook cells:
#'   common_per_loc  [B8]  = (test_entries - cross_entries) / locations
#'   unrep_per_loc   [B9]  = common_per_loc - prep_per_loc + cross_entries
#'   pure_test       [B10] = common_per_loc - prep_per_loc
#'   required_plots  [B11] = pure_test + cross_entries
#'                           + blocks * (prep_per_loc + check_entries)
#'   replication_ratio  [B13] = (check_entries + prep_per_loc) / total_entries_per_loc
#'   connectivity_ratio [B14] = (check_entries + cross_entries) / total_entries_per_loc
#'   field_plots     [D17] = field_rows * field_cols
#'   block_plots     [D18] = block_rows * block_cols
#'
#'   common_per_loc is deliberately NOT rounded. Keeping the fractional value is
#'   what lets gate G3 detect non-divisibility and report the exact numbers
#'   involved (Req 8.3).
#'
#'   Both ratios are returned as proportions in [0, 1]. Percentage formatting to
#'   one decimal place happens at render time, never here (Req 6.9).
#'
#'   Divisions guard against a zero or missing divisor by returning NA_real_
#'   instead of Inf/NaN, so the UI can render "unavailable" rather than a
#'   nonsense number.
compute_scenario <- function(params) {
  locations     <- scenario_num(params$locations)
  test_entries  <- scenario_num(params$test_entries)
  check_entries <- scenario_num(params$check_entries)
  cross_entries <- scenario_num(params$cross_entries)
  prep_per_loc  <- scenario_num(params$prep_per_loc)
  blocks        <- scenario_num(params$blocks)
  field_rows    <- scenario_num(params$field_rows)
  field_cols    <- scenario_num(params$field_cols)
  block_rows    <- scenario_num(params$block_rows)
  block_cols    <- scenario_num(params$block_cols)

  safe_divide <- function(numerator, denominator) {
    if (is.na(numerator) || is.na(denominator) || denominator == 0) return(NA_real_)
    numerator / denominator
  }

  common_per_loc <- safe_divide(test_entries - cross_entries, locations)          # B8
  unrep_per_loc  <- common_per_loc - prep_per_loc + cross_entries                # B9
  pure_test      <- common_per_loc - prep_per_loc                                # B10
  required_plots <- pure_test + cross_entries +
                    blocks * (prep_per_loc + check_entries)                      # B11

  total_entries_per_loc <- check_entries + prep_per_loc + unrep_per_loc
  replication_ratio  <- safe_divide(check_entries + prep_per_loc,  total_entries_per_loc)  # B13
  connectivity_ratio <- safe_divide(check_entries + cross_entries, total_entries_per_loc)  # B14

  field_plots <- field_rows * field_cols                                         # D17
  block_plots <- block_rows * block_cols                                         # D18

  block_size  <- safe_divide(required_plots, blocks)
  block_unrep <- safe_divide(unrep_per_loc,  blocks)
  block_size_summary <- sprintf(                                                 # A20
    "Block size = %s (%s Checks entries + %s P-Rep Test entries + %s Test entries)",
    format_scenario_number(block_size),
    format_scenario_number(check_entries),
    format_scenario_number(prep_per_loc),
    format_scenario_number(block_unrep)
  )

  list(
    common_per_loc        = common_per_loc,
    unrep_per_loc         = unrep_per_loc,
    pure_test             = pure_test,
    required_plots        = required_plots,
    total_entries_per_loc = total_entries_per_loc,
    replication_ratio     = replication_ratio,
    connectivity_ratio    = connectivity_ratio,
    field_plots           = field_plots,
    block_plots           = block_plots,
    block_size_summary    = block_size_summary
  )
}

#' Build the entry-type plot budget table (4 rows)
#'
#' @param params list — scenario inputs
#' @param derived list — output of compute_scenario()
#' @return data.frame(Entry_Type, Rep, Number, Plots)
#' @details Rows are emitted in the workbook's order with its verbatim labels
#'   (Req 11.1-11.5), and sum(Plots) equals derived$required_plots by
#'   construction (Req 11.6).
#'
#'   NAMING TRAP: the "Unreplicated Test Entries" row uses pure_test (B10), NOT
#'   unrep_per_loc (B9). B9 additionally counts the cross-location entries and
#'   is used only for the ratio denominator and the block size summary.
#'   Substituting B9 here yields a budget that looks nearly right but overshoots
#'   required_plots by cross_entries, and gate G1 then fails for a non-obvious
#'   reason.
build_plot_budget_table <- function(params, derived) {
  check_entries <- scenario_num(params$check_entries)
  cross_entries <- scenario_num(params$cross_entries)
  prep_per_loc  <- scenario_num(params$prep_per_loc)
  blocks        <- scenario_num(params$blocks)
  pure_test     <- derived$pure_test

  data.frame(
    Entry_Type = c(
      "Check Entries",
      "Test Entries Cross Locations",
      "Replicated Test Entries in P-Rep Design",
      "Unreplicated Test Entries"
    ),
    Rep = c(blocks, 1, blocks, 1),
    Number = c(check_entries, cross_entries, prep_per_loc, pure_test),
    Plots = c(
      blocks * check_entries,
      cross_entries,
      blocks * prep_per_loc,
      pure_test
    ),
    stringsAsFactors = FALSE
  )
}

#' Build one contiguous run of entry IDs, or integer(0) when the run is empty
#'
#' R's `:` operator counts DOWNWARD when the start exceeds the end, so
#' `52:51` silently yields a reversed length-2 vector where a zero-length vector
#' is meant. Every entry-ID segment therefore goes through this helper instead
#' of `:`. It also refuses to emit fractional IDs: when the offset or the count
#' is not a whole number (which happens when common_per_loc is fractional and
#' gate G3 is failing) the segment is empty rather than meaningless.
#'
#' @param start numeric — first ID of the run
#' @param count numeric — number of IDs in the run; 0 or negative yields none
#' @return integer vector, possibly integer(0)
entry_id_run <- function(start, count) {
  if (length(start) != 1 || length(count) != 1) return(integer(0))
  if (!is.finite(start) || !is.finite(count)) return(integer(0))
  if (abs(start - round(start)) > 1e-9) return(integer(0))
  if (abs(count - round(count)) > 1e-9) return(integer(0))
  count <- round(count)
  if (count <= 0) return(integer(0))
  as.integer(round(start)) + seq_len(as.integer(count)) - 1L
}

#' Compute the four numeric entry ID vectors for one location
#'
#' @param params list — scenario inputs
#' @param derived list — output of compute_scenario()
#' @param location integer — 1-based location number
#' @return list(cross = integer vector, prep = integer vector,
#'              unrep = integer vector, check = integer vector)
#' @details With C = common_per_loc, X = cross_entries, P = prep_per_loc,
#'   U = pure_test, K = check_entries, T = test_entries and L = location:
#'     cross = 1 : X                                           (identical for all L)
#'     prep  = (L-1)*C + X + 1     : (L-1)*C + X + P
#'     unrep = (L-1)*C + X + P + 1 : (L-1)*C + X + P + U
#'     check = T + 1               : T + K                     (identical for all L)
#'   (Req 12.2-12.6.)
#'
#'   The four vectors of one location are pairwise disjoint, and because
#'   P + U = C by definition of pure_test, the prep/unrep intervals of
#'   consecutive locations tile the ID space without overlap or gap.
#'
#'   Any of X, P, U or K may legitimately be zero — cross_entries and
#'   prep_per_loc both have a minimum of 0 — so an empty segment returns
#'   integer(0) rather than a descending sequence.
#'
#'   When common_per_loc is fractional (gate G3 failing) the offsets and counts
#'   stop being whole numbers. Rather than return fractional IDs, which are
#'   meaningless, the affected segments come back as integer(0). The cross and
#'   check segments are unaffected because their bounds do not involve C.
location_entry_ids <- function(params, derived, location) {
  X <- scenario_num(params$cross_entries)   # cross-location entries
  P <- scenario_num(params$prep_per_loc)    # P-Rep entries per location
  K <- scenario_num(params$check_entries)   # check entries
  Tot <- scenario_num(params$test_entries)  # total test entries
  C <- derived$common_per_loc               # B8, possibly fractional
  U <- derived$pure_test                    # B10, possibly fractional
  L <- scenario_num(location)

  base <- (L - 1) * C + X

  list(
    cross = entry_id_run(1,             X),
    prep  = entry_id_run(base + 1,      P),
    unrep = entry_id_run(base + P + 1,  U),
    check = entry_id_run(Tot + 1,       K)
  )
}

#' Format per-location entry ID ranges as a display table
#'
#' A thin formatting wrapper over location_entry_ids(), so the displayed table
#' and the engines that consume the IDs can never disagree (Req 12.1-12.6).
#'
#' @param params list — scenario inputs
#' @param derived list — output of compute_scenario()
#' @return data.frame — one row per entry type (row names carry the same
#'   verbatim labels as the plot budget table), one column per location named
#'   "1", "2", ..., each cell rendered "first - last". An empty segment renders
#'   as a single dash rather than raising an error.
build_entry_id_ranges <- function(params, derived) {
  labels <- c(
    "Check Entries",
    "Test Entries Cross Locations",
    "Replicated Test Entries in P-Rep Design",
    "Unreplicated Test Entries"
  )
  keys <- c("check", "cross", "prep", "unrep")

  locations <- scenario_num(params$locations)
  n_loc <- if (is.finite(locations) && locations >= 1) as.integer(floor(locations)) else 0L
  if (n_loc == 0L) return(data.frame(row.names = labels))

  format_range <- function(v) {
    if (length(v) == 0) return("-")
    paste0(v[1], " - ", v[length(v)])
  }

  columns <- lapply(seq_len(n_loc), function(loc) {
    ids <- location_entry_ids(params, derived, loc)
    vapply(keys, function(k) format_range(ids[[k]]), character(1), USE.NAMES = FALSE)
  })

  out <- as.data.frame(columns, stringsAsFactors = FALSE)
  names(out) <- as.character(seq_len(n_loc))
  rownames(out) <- labels
  out
}

#' Parse a comma-delimited check-name string, with fallback naming
#'
#' @param text character — raw user input, may be NULL, NA or empty
#' @param n integer — expected count (check_entries)
#' @return list(names = character vector, used_fallback = logical,
#'              count_mismatch = logical)
#' @details Splits on ",", trims leading/trailing whitespace from each token and
#'   drops empty tokens. NULL, empty or whitespace-only input yields
#'   paste0("check", seq_len(n)) with used_fallback = TRUE and
#'   count_mismatch = FALSE. Otherwise used_fallback is FALSE and
#'   count_mismatch is TRUE exactly when the parsed count differs from n
#'   (Req 9.3-9.6).
#'
#'   n is guarded: when n is missing, NA or below 1 the fallback is
#'   character(0) rather than an error, because the check-entry input may still
#'   be empty while the App is starting up.
parse_check_names <- function(text, n) {
  n_num <- scenario_num(n)
  n_int <- if (is.finite(n_num) && n_num >= 1) as.integer(floor(n_num)) else 0L
  fallback <- if (n_int >= 1L) paste0("check", seq_len(n_int)) else character(0)

  raw <- if (is.null(text) || length(text) == 0 || all(is.na(text))) {
    ""
  } else {
    paste(as.character(text[!is.na(text)]), collapse = ",")
  }

  tokens <- trimws(strsplit(raw, ",", fixed = TRUE)[[1]])
  tokens <- tokens[nzchar(tokens)]

  if (length(tokens) == 0) {
    return(list(names = fallback, used_fallback = TRUE, count_mismatch = FALSE))
  }

  list(
    names          = tokens,
    used_fallback  = FALSE,
    count_mismatch = length(tokens) != n_int
  )
}

# -----------------------------------------------------------------------------
# 5. Validation Functions
# -----------------------------------------------------------------------------

#' Validate the three hard plot-budget gates and the ratio thresholds
#'
#' @param params list — scenario inputs
#' @param derived list — output of compute_scenario()
#' @return list(valid = logical, errors = character, warnings = character,
#'              gates = list(G1 = logical, G2 = logical, G3 = logical))
#' @details Gates, each reported independently so the UI can badge them one by
#'   one (Req 8.1-8.5):
#'     G1  required_plots == field_plots
#'     G2  block_rows * block_cols * blocks == field_plots
#'     G3  (test_entries - cross_entries) mod locations == 0
#'   G1 compares a possibly fractional required_plots against an integer plot
#'   count, so the comparison carries a 1e-9 tolerance.
#'
#'   The ratio threshold messages (Req 13) come back from this same call so the
#'   Scenario Panel has ONE status source. They are advisory: they populate
#'   `warnings`/`errors` but NEVER affect `valid`, and therefore never block
#'   design generation. Only G1, G2 and G3 do that.
validate_plot_budget <- function(params, derived) {
  errors   <- character(0)
  warnings <- character(0)
  tol      <- 1e-9

  test_entries <- scenario_num(params$test_entries)
  cross_entries <- scenario_num(params$cross_entries)
  locations    <- scenario_num(params$locations)
  blocks       <- scenario_num(params$blocks)
  block_rows   <- scenario_num(params$block_rows)
  block_cols   <- scenario_num(params$block_cols)

  fmt <- format_scenario_number

  # --- G1: required plots per location must fill the field exactly -----------
  g1_diff <- derived$required_plots - derived$field_plots
  gate_g1 <- !is.na(g1_diff) && abs(g1_diff) <= tol
  if (!gate_g1) {
    if (is.na(g1_diff)) {
      errors <- c(errors, paste0(
        "Gate G1 cannot be evaluated: Required plots per location or Field Plots ",
        "is missing or non-numeric."
      ))
    } else {
      errors <- c(errors, sprintf(
        paste0("Gate G1 failed: Required plots per location (%s) does not equal ",
               "Field Plots (%s); difference = %s. Adjust the scenario counts or ",
               "the field dimensions until the two agree."),
        fmt(derived$required_plots), fmt(derived$field_plots), fmt(g1_diff)
      ))
    }
  }

  # --- G2: the block grid tiled `blocks` times must fill the field ----------
  block_plot_total <- block_rows * block_cols * blocks
  g2_diff <- block_plot_total - derived$field_plots
  gate_g2 <- !is.na(g2_diff) && abs(g2_diff) <= tol
  if (!gate_g2) {
    if (is.na(g2_diff)) {
      errors <- c(errors, paste0(
        "Gate G2 cannot be evaluated: the block dimensions, Augmented blocks or ",
        "Field Plots value is missing or non-numeric."
      ))
    } else {
      errors <- c(errors, sprintf(
        paste0("Gate G2 failed: Block Rows x Block Columns x Augmented blocks (%s) ",
               "does not equal Field Plots (%s); difference = %s."),
        fmt(block_plot_total), fmt(derived$field_plots), fmt(g2_diff)
      ))
    }
  }

  # --- G3: the common test entries per location must be a whole number ------
  gate_g3 <- FALSE
  if (is.na(test_entries) || is.na(cross_entries) || is.na(locations) || locations == 0) {
    errors <- c(errors, paste0(
      "Gate G3 cannot be evaluated: Test entries, Entries cross locations or ",
      "Locations is missing, non-numeric or zero."
    ))
  } else {
    remainder <- (test_entries - cross_entries) %% locations
    gate_g3 <- abs(remainder) <= tol || abs(remainder - locations) <= tol
    if (!gate_g3) {
      errors <- c(errors, sprintf(
        paste0("Gate G3 failed: (Test entries - Entries cross locations) must divide ",
               "evenly by Locations. Test entries = %s, Entries cross locations = %s, ",
               "Locations = %s; (%s - %s) / %s = %s, leaving a remainder of %s."),
        fmt(test_entries), fmt(cross_entries), fmt(locations),
        fmt(test_entries), fmt(cross_entries), fmt(locations),
        fmt(derived$common_per_loc), fmt(remainder)
      ))
    }
  }

  # --- Ratio thresholds (Req 13) — advisory only, never gating --------------
  replication_pct  <- derived$replication_ratio  * 100
  connectivity_pct <- derived$connectivity_ratio * 100

  if (!is.na(replication_pct) && replication_pct < THRESHOLD_REPLICATION_WARNING) {
    warnings <- c(warnings, sprintf(
      paste0("Replication Ratio (%.1f%%) is below the recommended minimum of %d%% ",
             "(Cullis et al., 2006)."),
      replication_pct, THRESHOLD_REPLICATION_WARNING
    ))
  }

  if (!is.na(connectivity_pct)) {
    if (connectivity_pct < THRESHOLD_CONNECTIVITY_ERROR) {
      errors <- c(errors, sprintf(
        paste0("Connectivity Ratio (%.1f%%) is below %d%%; prediction accuracy and ",
               "model stability decline significantly below %d%%."),
        connectivity_pct, THRESHOLD_CONNECTIVITY_ERROR, THRESHOLD_CONNECTIVITY_ERROR
      ))
    } else if (connectivity_pct < THRESHOLD_CONNECTIVITY_WARNING) {
      warnings <- c(warnings, sprintf(
        paste0("Connectivity Ratio (%.1f%%) is below the recommended 15-20%% overlap ",
               "(Jarquin et al., 2020)."),
        connectivity_pct
      ))
    }
  }

  list(
    valid    = gate_g1 && gate_g2 && gate_g3,
    errors   = errors,
    warnings = warnings,
    gates    = list(G1 = gate_g1, G2 = gate_g2, G3 = gate_g3)
  )
}

#' Validate one numeric scenario input against its minimum
#'
#' @param value numeric|character|NULL — raw input value
#' @param min_value numeric — smallest acceptable value
#' @param label character — parameter name used in the message
#' @param integer_only logical — TRUE when only whole numbers are acceptable
#' @return character — "" when acceptable, otherwise the error text
#' @details Errors when the value is missing, empty, non-numeric, non-integer
#'   where integers are required, or below min_value (Req 25.1-25.4).
#'
#'   For continuous inputs (integer_only = FALSE) the minimum is EXCLUSIVE,
#'   which encodes the seed grams per plot rule of strictly greater than zero
#'   (Req 10.4). For integer inputs the minimum is inclusive.
validate_numeric_input <- function(value, min_value, label, integer_only = TRUE) {
  bound_text <- if (integer_only) {
    sprintf("a whole number of at least %s", format_scenario_number(min_value))
  } else {
    sprintf("a number greater than %s", format_scenario_number(min_value))
  }

  if (is.null(value) || length(value) == 0) {
    return(sprintf("%s is required; enter %s.", label, bound_text))
  }
  raw <- value[[1]]
  if (is.character(raw) && !nzchar(trimws(raw))) {
    return(sprintf("%s is required; enter %s.", label, bound_text))
  }
  numeric_value <- suppressWarnings(as.numeric(raw))
  if (is.na(numeric_value)) {
    return(sprintf("%s must be numeric; enter %s.", label, bound_text))
  }
  if (integer_only && !isTRUE(all.equal(numeric_value, round(numeric_value)))) {
    return(sprintf(
      "%s must be a whole number; %s is not an integer. Enter %s.",
      label, format_scenario_number(numeric_value), bound_text
    ))
  }
  if (integer_only) {
    if (numeric_value < min_value) {
      return(sprintf(
        "%s must be at least %s; %s is too small.",
        label, format_scenario_number(min_value), format_scenario_number(numeric_value)
      ))
    }
  } else if (numeric_value <= min_value) {
    return(sprintf(
      "%s must be greater than %s; %s is not acceptable.",
      label, format_scenario_number(min_value), format_scenario_number(numeric_value)
    ))
  }
  ""
}

#' Cross-parameter consistency checks
#'
#' @param params list — scenario inputs
#' @param derived list — output of compute_scenario()
#' @return list(errors = character)
#' @details cross_entries <= test_entries (Req 25.5);
#'   prep_per_loc <= common_per_loc, i.e. pure_test >= 0 (Req 25.6).
validate_parameter_consistency <- function(params, derived) {
  errors <- character(0)
  fmt <- format_scenario_number

  test_entries  <- scenario_num(params$test_entries)
  cross_entries <- scenario_num(params$cross_entries)
  prep_per_loc  <- scenario_num(params$prep_per_loc)

  if (!is.na(test_entries) && !is.na(cross_entries) && cross_entries > test_entries) {
    errors <- c(errors, sprintf(
      paste0("Entries cross locations (%s) cannot exceed Test entries (%s)."),
      fmt(cross_entries), fmt(test_entries)
    ))
  }

  if (!is.na(prep_per_loc) && !is.na(derived$common_per_loc) &&
      prep_per_loc > derived$common_per_loc) {
    errors <- c(errors, sprintf(
      paste0("P-Rep test entries per location (%s) exceeds Test entries but common ",
             "per location (%s); Pure test entries would become negative (%s)."),
      fmt(prep_per_loc), fmt(derived$common_per_loc), fmt(derived$pure_test)
    ))
  }

  list(errors = errors)
}

#' Validate entries data frame
#'
#' @param df data.frame — raw uploaded entries
#' @return list(valid = logical, data = data.frame|NULL,
#'              summary = list(n, min_available, max_available, n_families),
#'              errors = character)
#' @details valid iff Code/SELHIS/Available are all present, every Available
#'   value is numeric and greater than zero, and every Code value is unique.
#'   Errors name the missing columns, the invalid Available row numbers and the
#'   duplicated Code values (Req 4.2-4.6). On success the derived Family column
#'   is added and `summary` reports nrow(df) as Test_Entries (Req 3.4), the
#'   Available range — whose minimum pre-fills seed grams per plot (Req 4.6,
#'   10.2) — and the unique family count. `summary` is NULL whenever validation
#'   fails, so callers must branch on `valid` before reading it.
validate_entries <- function(df) {
  errors <- character()

  required_cols <- c("Code", "SELHIS", "Available")
  missing_cols <- setdiff(required_cols, names(df))
  if (length(missing_cols) > 0) {
    for (col in missing_cols) {
      errors <- c(errors, paste0("Missing required column: ", col))
    }
    return(list(valid = FALSE, data = NULL, summary = NULL, errors = errors))
  }

  available_values <- suppressWarnings(as.numeric(df$Available))
  invalid_rows <- which(is.na(available_values) | available_values <= 0)
  if (length(invalid_rows) > 0) {
    errors <- c(errors, paste0(
      "Available column contains non-numeric or non-positive values in rows: ",
      paste(invalid_rows, collapse = ", ")
    ))
  }

  if (any(duplicated(df$Code))) {
    dup_codes <- unique(df$Code[duplicated(df$Code)])
    errors <- c(errors, paste0(
      "Code column contains duplicate values: ",
      paste(dup_codes, collapse = ", ")
    ))
  }

  if (length(errors) > 0) {
    return(list(valid = FALSE, data = NULL, summary = NULL, errors = errors))
  }

  df$Available <- as.numeric(df$Available)
  df$Family <- derive_family(df$SELHIS)

  summary <- list(
    n             = nrow(df),
    min_available = if (nrow(df) > 0) min(df$Available) else NA_real_,
    max_available = if (nrow(df) > 0) max(df$Available) else NA_real_,
    n_families    = length(unique(df$Family))
  )

  return(list(valid = TRUE, data = df, summary = summary, errors = character()))
}

#' Validate pedigree matrix
#'
#' @param mat matrix — parsed pedigree similarity matrix
#' @param entry_codes character — Code values of the uploaded Entry_Table
#' @return list(valid = logical, data = matrix|NULL, errors = character,
#'              warnings = character,
#'              summary = list(nrow, ncol, n_matched, n_unmatched)|NULL)
#' @details Validation logic and message text are fixed by
#'   tests/testthat/test-validation-pedigree.R and are unchanged. `summary` is
#'   populated only when `valid` is TRUE and is NULL on every failure path, so
#'   callers must branch on `valid` before reading it. The Scenario Panel needs
#'   it to show the matrix dimensions and the matched-entry count (Req 5.6).
validate_pedigree <- function(mat, entry_codes) {
  errors   <- character(0)
  warnings <- character(0)

  if (!is.numeric(mat)) {
    errors <- c(errors, "Pedigree matrix contains non-numeric values")
    return(list(valid = FALSE, data = NULL, errors = errors, warnings = warnings,
                summary = NULL))
  }

  if (nrow(mat) != ncol(mat)) {
    errors <- c(errors, sprintf("Pedigree matrix is not square: %d rows and %d columns", nrow(mat), ncol(mat)))
    return(list(valid = FALSE, data = NULL, errors = errors, warnings = warnings,
                summary = NULL))
  }

  rn <- rownames(mat)
  cn <- colnames(mat)

  if (is.null(rn) || is.null(cn)) {
    errors <- c(errors, "Pedigree matrix is missing row names or column names")
    return(list(valid = FALSE, data = NULL, errors = errors, warnings = warnings,
                summary = NULL))
  }

  if (!identical(rn, cn)) {
    errors <- c(errors, "Pedigree matrix row names do not match column names")
    return(list(valid = FALSE, data = NULL, errors = errors, warnings = warnings,
                summary = NULL))
  }

  diff_mat <- abs(mat - t(mat))
  if (any(diff_mat > PEDIGREE_SYMMETRY_TOLERANCE)) {
    n_asymmetric <- sum(diff_mat > PEDIGREE_SYMMETRY_TOLERANCE) / 2
    errors <- c(errors, sprintf("Pedigree matrix is not symmetric: %d cell pair(s) differ", as.integer(n_asymmetric)))
    return(list(valid = FALSE, data = NULL, errors = errors, warnings = warnings,
                summary = NULL))
  }

  matrix_codes <- rn
  unmatched <- setdiff(matrix_codes, entry_codes)
  matched_count <- length(intersect(matrix_codes, entry_codes))

  if (length(unmatched) > 0) {
    warnings <- c(warnings, sprintf(
      "%d entry code(s) in pedigree matrix not found in Entry_Table (%d of %d matched)",
      length(unmatched), matched_count, length(matrix_codes)
    ))
  }

  list(
    valid    = TRUE,
    data     = mat,
    errors   = errors,
    warnings = warnings,
    summary  = list(
      nrow        = nrow(mat),
      ncol        = ncol(mat),
      n_matched   = matched_count,
      n_unmatched = length(unmatched)
    )
  )
}

# -----------------------------------------------------------------------------
# 6. Allocation Engine Functions (Pure)
# -----------------------------------------------------------------------------

#' Keep only the entries holding enough seed for the plots they will occupy
#'
#' @param entries data.frame — must carry an Available column in grams
#' @param seed_per_plot numeric — grams sown per plot
#' @param multiplier numeric — plots the entry will occupy: locations for a
#'   cross-location entry, blocks for a P-Rep entry
#' @return data.frame — exactly the rows with Available >= seed_per_plot *
#'   multiplier, in their original order (Req 14.1, 15.1)
#' @details The single place the seed rule is expressed, so the two allocators
#'   can never drift apart. A non-finite seed quantity or multiplier admits
#'   nothing rather than everything: an unset seed input must not silently pass
#'   every entry through the gate. Non-numeric Available values are likewise
#'   rejected, though validate_entries() should have caught them first.
filter_by_seed <- function(entries, seed_per_plot, multiplier) {
  if (is.null(entries) || nrow(entries) == 0) return(entries)

  seed <- scenario_num(seed_per_plot)
  mult <- scenario_num(multiplier)
  if (!is.finite(seed) || !is.finite(mult)) return(entries[0, , drop = FALSE])

  available <- suppressWarnings(as.numeric(entries$Available))
  keep <- !is.na(available) & available >= seed * mult
  entries[keep, , drop = FALSE]
}

#' Iteratively remove the entry holding the highest pedigree similarity
#'
#' @param candidates data.frame — seed-qualified entries, must carry Code
#' @param pedigree matrix — symmetric similarity matrix, dimnames are entry codes
#' @param target_count integer — number of entries to keep
#' @param progress_callback function(current, total)|NULL
#' @return data.frame — target_count rows, always a subset of candidates
#' @details Ties on the maximum similarity are broken at random among every
#'   entry involved in a tied pair (Req 14.4, 15.2). Kept as a general utility
#'   taking a loose target_count, because both allocators call it with a
#'   different target computed from `derived`.
#'
#'   PEDIGREE COVERAGE: validate_pedigree() only WARNS when the matrix and the
#'   Entry_Table disagree, so the matrix may legitimately cover a subset of the
#'   candidates. Subsetting pedigree[codes, codes] with an uncovered code raises
#'   "subscript out of bounds", which would abort allocation over a warning the
#'   user was told to expect. Candidates are therefore restricted to the codes
#'   present in rownames(pedigree), and when fewer than target_count candidates
#'   have coverage the function falls back to the first target_count candidates
#'   unfiltered — no diversity optimisation is possible, but allocation
#'   proceeds.
filter_by_diversity <- function(candidates, pedigree, target_count, progress_callback = NULL) {
  if (is.null(candidates)) return(candidates)
  target_count <- scenario_num(target_count)
  if (!is.finite(target_count) || target_count < 0) return(candidates)
  if (nrow(candidates) <= target_count) return(candidates)
  target_count <- as.integer(round(target_count))

  ped_codes <- if (is.matrix(pedigree)) rownames(pedigree) else NULL
  covered <- if (is.null(ped_codes)) character(0) else intersect(candidates$Code, ped_codes)

  # Not enough pedigree coverage to optimise on: take the first target_count.
  if (length(covered) < target_count) {
    return(candidates[seq_len(target_count), , drop = FALSE])
  }

  work <- candidates[candidates$Code %in% covered, , drop = FALSE]
  ped_sub <- pedigree[work$Code, work$Code, drop = FALSE]
  diag(ped_sub) <- 0

  total_iterations <- nrow(work) - target_count

  for (iteration in seq_len(total_iterations)) {
    max_sim <- max(ped_sub)
    max_positions <- which(ped_sub == max_sim, arr.ind = TRUE)
    involved_indices <- unique(c(max_positions[, "row"], max_positions[, "col"]))
    involved_codes <- rownames(ped_sub)[involved_indices]
    remove_code <- if (length(involved_codes) == 1) involved_codes else sample(involved_codes, 1)
    keep_idx <- rownames(ped_sub) != remove_code
    ped_sub <- ped_sub[keep_idx, keep_idx, drop = FALSE]

    if (is.function(progress_callback)) {
      progress_callback(iteration, total_iterations)
    }
  }

  remaining_codes <- rownames(ped_sub)
  candidates[candidates$Code %in% remaining_codes, , drop = FALSE]
}

#' Allocate cross-location entries with adaptive seed relaxation
#'
#' @param entries data.frame — validated entries (Code, SELHIS, Available, Family)
#' @param pedigree matrix — validated similarity matrix
#' @param params list — scenario inputs, supplies cross_entries, locations and
#'   seed_per_plot
#' @param derived list — output of compute_scenario(), accepted for signature
#'   symmetry with the other allocators
#' @param progress_callback function(current, total)|NULL
#' @return list(selected = data.frame, remaining = data.frame,
#'              packs_used = integer, warnings = character)
#' @details The target is params$cross_entries and the seed multiplier starts at
#'   params$locations, so both come from the arithmetic layer rather than from a
#'   loose count the caller computed for itself (Req 14.1).
#'
#'   ADAPTIVE RELAXATION: while fewer entries qualify than the target needs the
#'   pack count drops by one and the seed filter runs again, stopping at 1. A
#'   relaxation that was actually applied is reported as a warning naming the
#'   qualifying count and the reduced pack count (Req 14.2, 14.3).
allocate_cross_location <- function(entries, pedigree, params, derived,
                                    progress_callback = NULL) {
  warnings <- character(0)

  target_count  <- as_whole_count(params$cross_entries)
  num_locations <- as_whole_count(params$locations)
  seed_per_plot <- scenario_num(params$seed_per_plot)

  if (is.na(target_count)) target_count <- 0L
  if (is.na(num_locations) || num_locations < 1L) num_locations <- 1L

  if (target_count == 0L) {
    return(list(selected = entries[0, , drop = FALSE], remaining = entries,
                packs_used = num_locations, warnings = warnings))
  }

  pack_count <- num_locations
  qualifying <- filter_by_seed(entries, seed_per_plot, pack_count)

  while (nrow(qualifying) < target_count && pack_count > 1L) {
    pack_count <- pack_count - 1L
    qualifying <- filter_by_seed(entries, seed_per_plot, pack_count)
  }

  if (pack_count < num_locations) {
    warnings <- c(warnings, sprintf(
      paste0("%d entries present at %d locations (seed shortage detected); entries with ",
             "insufficient seed for all %d locations will be randomly replaced by ",
             "commercial checks where needed to fill the gaps"),
      nrow(qualifying), pack_count, num_locations))
  }

  if (nrow(qualifying) >= target_count) {
    selected <- filter_by_diversity(qualifying, pedigree, target_count, progress_callback)
  } else {
    selected <- qualifying
    warnings <- c(warnings, sprintf(
      "Only %d entries qualify for cross-location (target was %d)",
      nrow(selected), target_count))
  }

  remaining <- entries[!entries$Code %in% selected$Code, , drop = FALSE]
  list(selected = selected, remaining = remaining,
       packs_used = pack_count, warnings = warnings)
}

#' Allocate P-Rep entries
#'
#' @param entries data.frame — the entries left after cross-location allocation
#' @param pedigree matrix — validated similarity matrix
#' @param params list — scenario inputs, supplies locations, prep_per_loc,
#'   blocks and seed_per_plot
#' @param derived list — output of compute_scenario(), accepted for signature
#'   symmetry with the other allocators
#' @param progress_callback function(current, total)|NULL
#' @return list(selected = data.frame, remaining = data.frame, errors = character)
#' @details Target is params$locations * params$prep_per_loc and the seed
#'   multiplier is params$blocks, because a P-Rep entry occupies one plot in each
#'   augmented block of its single location (Req 15.1, 15.2).
#'
#'   A shortfall is a hard error, not a warning: silently shrinking the P-Rep set
#'   would break the plot budget the gates already approved. The message names
#'   the shortfall count and the applied threshold (Req 15.3).
allocate_p_rep <- function(entries, pedigree, params, derived,
                           progress_callback = NULL) {
  locations    <- as_whole_count(params$locations)
  prep_per_loc <- as_whole_count(params$prep_per_loc)
  blocks       <- as_whole_count(params$blocks)
  seed_per_plot <- scenario_num(params$seed_per_plot)

  if (is.na(locations) || locations < 1L) locations <- 1L
  if (is.na(prep_per_loc)) prep_per_loc <- 0L
  target_count <- locations * prep_per_loc

  if (target_count == 0L) {
    return(list(selected = entries[0, , drop = FALSE], remaining = entries,
                errors = character(0)))
  }

  multiplier <- if (is.na(blocks)) NA_integer_ else blocks
  qualifying <- filter_by_seed(entries, seed_per_plot, multiplier)
  threshold  <- seed_per_plot * scenario_num(multiplier)

  if (nrow(qualifying) < target_count) {
    error_msg <- sprintf(
      paste0("Only %d entries meet the seed threshold (%s g) for P-Rep; %d required ",
             "(shortfall of %d entries)"),
      nrow(qualifying), format_scenario_number(threshold), target_count,
      target_count - nrow(qualifying))
    return(list(selected = entries[0, , drop = FALSE], remaining = entries,
                errors = error_msg))
  }

  selected <- filter_by_diversity(qualifying, pedigree, target_count, progress_callback)
  remaining <- entries[!entries$Code %in% selected$Code, , drop = FALSE]
  list(selected = selected, remaining = remaining, errors = character(0))
}

#' Perform complete entry allocation and resolve every numeric entry ID
#'
#' @param entries data.frame — validated entries (Code, SELHIS, Available, Family)
#' @param pedigree matrix — validated similarity matrix
#' @param params list — scenario inputs, including seed_per_plot
#' @param derived list — output of compute_scenario()
#' @param check_names character vector — parse_check_names()$names
#' @param progress_callback function(current, total)|NULL
#' @return list(cross_location, p_rep, unreplicated, check, entry_code_map,
#'              warnings, errors)
#' @details Each of the four entry frames carries Location, Entry_Type and
#'   Entry_ID alongside the uploaded columns. Entry_Type holds "Cross", "P-Rep",
#'   "Unreplicated" or "Check" — the names of ENTRY_TYPE_COLOURS — so the layout
#'   renderer and the diagnostics key off it directly. It replaces the former
#'   Theme column, whose values matched nothing.
#'
#'   ENTRY IDs come from location_entry_ids(), the same source the Randomization
#'   Engine and the Script Generator use, which is what makes a field book Entry
#'   value resolvable through entry_code_map (Req 21.1). Cross-location entries
#'   take IDs 1..cross_entries at every location, checks take
#'   test_entries+1..test_entries+check_entries, and each location's P-Rep and
#'   unreplicated entries take that location's prep and unrep segments. Within a
#'   (location, type) group the IDs are handed out positionally, in the order the
#'   entries come out of the diversity filter and the round-robin distribution.
#'
#'   GROUP SIZE MISMATCH: when a group holds a different number of entries than
#'   its ID segment holds IDs, the allocation and the arithmetic have diverged.
#'   The surplus entries get NA and a warning names the group and both counts,
#'   rather than truncating silently and shipping a design whose entry IDs do not
#'   line up with the field books.
#'
#'   entry_code_map has exactly Location, Entry_Type, Entry_ID, Code, SELHIS,
#'   Available, Family, ordered by Location then Entry_ID. Location is character
#'   because it carries the string "All" for the cross-location and check entries
#'   — shared by every location — beside the location number for the entries that
#'   belong to a single location. "All" sorts first, then locations numerically
#'   rather than lexically, so location 10 follows location 9.
allocate_entries <- function(entries, pedigree, params, derived, check_names,
                             progress_callback = NULL) {
  all_warnings <- character(0)
  all_errors   <- character(0)

  n_loc <- as_whole_count(params$locations)
  if (is.na(n_loc) || n_loc < 1L) n_loc <- 1L

  # ID segments. cross and check are identical at every location, so location 1
  # is a valid source for both.
  ids_shared <- location_entry_ids(params, derived, 1)

  # Hand out one ID segment to one (location, type) group, positionally.
  assign_ids <- function(df, ids, group_label) {
    n <- nrow(df)
    out <- rep(NA_integer_, n)
    if (n != length(ids)) {
      all_warnings <<- c(all_warnings, sprintf(
        paste0("%s: allocation produced %d entries but the entry ID range holds %d IDs; ",
               "the allocation and the scenario arithmetic have diverged"),
        group_label, n, length(ids)))
    }
    k <- min(n, length(ids))
    if (k > 0) out[seq_len(k)] <- as.integer(ids[seq_len(k)])
    out
  }

  # --- Cross-location entries -------------------------------------------------
  cross_result <- allocate_cross_location(
    entries = entries, pedigree = pedigree, params = params, derived = derived,
    progress_callback = progress_callback
  )
  all_warnings <- c(all_warnings, cross_result$warnings)

  cross_location <- cross_result$selected
  cross_location$Location   <- rep("All", nrow(cross_location))
  cross_location$Entry_Type <- rep("Cross", nrow(cross_location))
  cross_location$Entry_ID   <- assign_ids(cross_location, ids_shared$cross, "Cross entries")

  # --- Check entries ----------------------------------------------------------
  check_names <- if (is.null(check_names)) character(0) else as.character(check_names)
  check_df <- data.frame(
    Code       = check_names,
    SELHIS     = rep(NA_character_, length(check_names)),
    Available  = rep(NA_real_,      length(check_names)),
    Family     = rep(NA_character_, length(check_names)),
    Location   = rep("All",         length(check_names)),
    Entry_Type = rep("Check",       length(check_names)),
    stringsAsFactors = FALSE
  )
  check_df$Entry_ID <- assign_ids(check_df, ids_shared$check, "Check entries")

  # --- P-Rep entries ----------------------------------------------------------
  p_rep_result <- allocate_p_rep(
    entries = cross_result$remaining, pedigree = pedigree, params = params,
    derived = derived, progress_callback = progress_callback
  )

  if (length(p_rep_result$errors) > 0) {
    all_errors <- c(all_errors, p_rep_result$errors)
    empty <- entries[0, , drop = FALSE]
    return(list(cross_location = cross_location, p_rep = empty,
                unreplicated = empty, check = check_df,
                entry_code_map = allocation_code_map(list()),
                warnings = all_warnings, errors = all_errors))
  }

  p_rep_distributed <- distribute_round_robin(p_rep_result$selected, n_loc)
  p_rep_distributed$Entry_Type <- rep("P-Rep", nrow(p_rep_distributed))

  # --- Unreplicated entries: everything the two allocators left behind --------
  unreplicated_distributed <- distribute_round_robin(p_rep_result$remaining, n_loc)
  unreplicated_distributed$Entry_Type <- rep("Unreplicated", nrow(unreplicated_distributed))

  # --- Per-location entry IDs for the two single-location types ---------------
  p_rep_distributed$Entry_ID        <- rep(NA_integer_, nrow(p_rep_distributed))
  unreplicated_distributed$Entry_ID <- rep(NA_integer_, nrow(unreplicated_distributed))

  for (loc in seq_len(n_loc)) {
    ids <- location_entry_ids(params, derived, loc)

    prep_rows <- which(p_rep_distributed$Location == loc)
    p_rep_distributed$Entry_ID[prep_rows] <- assign_ids(
      p_rep_distributed[prep_rows, , drop = FALSE], ids$prep,
      sprintf("P-Rep entries at location %d", loc))

    unrep_rows <- which(unreplicated_distributed$Location == loc)
    unreplicated_distributed$Entry_ID[unrep_rows] <- assign_ids(
      unreplicated_distributed[unrep_rows, , drop = FALSE], ids$unrep,
      sprintf("Unreplicated entries at location %d", loc))
  }

  entry_code_map <- allocation_code_map(list(
    cross_location, p_rep_distributed, unreplicated_distributed, check_df))

  list(cross_location = cross_location, p_rep = p_rep_distributed,
       unreplicated = unreplicated_distributed, check = check_df,
       entry_code_map = entry_code_map, warnings = all_warnings, errors = all_errors)
}

#' Stack allocated entry frames into the entry code map
#'
#' @param parts list of data.frames carrying Location, Entry_Type, Entry_ID,
#'   Code, SELHIS, Available and Family
#' @return data.frame with exactly those seven columns, ordered by Location
#'   ("All" first, then numerically) then Entry_ID
allocation_code_map <- function(parts) {
  cols <- c("Location", "Entry_Type", "Entry_ID", "Code", "SELHIS", "Available", "Family")

  empty <- data.frame(
    Location = character(0), Entry_Type = character(0), Entry_ID = integer(0),
    Code = character(0), SELHIS = character(0), Available = numeric(0),
    Family = character(0), stringsAsFactors = FALSE
  )

  keep <- Filter(function(df) !is.null(df) && nrow(df) > 0, parts)
  if (length(keep) == 0) return(empty)

  normalised <- lapply(keep, function(df) {
    data.frame(
      Location   = as.character(df$Location),
      Entry_Type = as.character(df$Entry_Type),
      Entry_ID   = as.integer(df$Entry_ID),
      Code       = as.character(df$Code),
      SELHIS     = if ("SELHIS" %in% names(df)) as.character(df$SELHIS) else NA_character_,
      Available  = if ("Available" %in% names(df)) as.numeric(df$Available) else NA_real_,
      Family     = if ("Family" %in% names(df)) as.character(df$Family) else NA_character_,
      stringsAsFactors = FALSE
    )
  })

  out <- do.call(rbind, normalised)

  loc_key <- suppressWarnings(as.numeric(out$Location))
  loc_key[is.na(loc_key)] <- 0            # "All" sorts ahead of location 1
  out <- out[order(loc_key, out$Entry_ID), cols, drop = FALSE]
  rownames(out) <- NULL
  out
}

#' Distribute entries across locations by family in round-robin
#'
#' @param entries data.frame — must carry a Family column
#' @param num_locations integer
#' @return data.frame — sorted by Family with an integer Location column 1..N
#' @details Remainder entries land on the earliest locations, so no two location
#'   counts differ by more than 1 (Req 15.4, 16.2, 16.3).
distribute_round_robin <- function(entries, num_locations) {
  if (is.null(entries)) return(entries)
  if (nrow(entries) == 0) {
    entries$Location <- integer(0)
    return(entries)
  }
  entries <- entries[order(entries$Family), , drop = FALSE]
  entries$Location <- rep(seq_len(num_locations), length.out = nrow(entries))
  rownames(entries) <- NULL
  entries
}

# -----------------------------------------------------------------------------
# 7. Randomization Engine Functions
# -----------------------------------------------------------------------------
#
# compute_field_dimensions() is gone: field and block dimensions are user inputs
# now, so nothing derives them. randomize_location() executes exactly the
# statements generate_digger_script() emits, in the same order, using the same
# integers, and it draws its entry IDs from location_entry_ids() — the same call
# the Script Generator makes (Req 17.11).

#' Coerce one scenario value to a whole number, or NA_integer_ when impossible
#'
#' rep(), seq_len() and matrix() all refuse fractional or missing counts, and the
#' failures they raise are opaque. Every count entering the engine passes through
#' here so the engine can report a readable error instead.
#'
#' @param x numeric|character|NULL
#' @return integer, or NA_integer_ when the value is absent, non-finite or not whole
as_whole_count <- function(x) {
  v <- scenario_num(x)
  if (!is.finite(v)) return(NA_integer_)
  if (abs(v - round(v)) > 1e-9) return(NA_integer_)
  as.integer(round(v))
}

#' Rebuild the field layout matrix from a fitted design
#'
#' Mirrors the three script statements
#'   layout <- getDesign(design)
#'   layout <- sapply(layout, function(x) trt.name[match(x, 1:entries)])
#'   dim(layout) <- c(field.rows, field.cols)
#'
#' The remap is essential, not cosmetic: getDesign() returns the internal
#' treatment codes 1..entries, NOT the treatment names, so skipping it would put
#' wrong entry IDs into the layout.
#'
#' TEST SEAM: when DiGGer is absent (a stub design was injected) getDesign() does
#' not exist, so the layout is reconstructed from the plot-level dlist
#' coordinates instead. Both paths produce the same field_rows x field_cols
#' matrix of entry IDs.
#'
#' @param design list — fitted design object (or stub)
#' @param trt_name numeric vector — treatment names in treatRepPerRep order
#' @param entries integer — number of treatments
#' @param field_rows,field_cols integer — field dimensions
#' @return numeric matrix of entry IDs, or NULL when neither path is available
design_layout_matrix <- function(design, trt_name, entries, field_rows, field_cols) {
  codes <- NULL
  if (check_digger_available()) {
    codes <- tryCatch(DiGGer::getDesign(design), error = function(e) NULL)
  }

  if (!is.null(codes) && length(codes) == field_rows * field_cols) {
    layout <- as.numeric(sapply(codes, function(x) trt_name[match(x, seq_len(entries))]))
    dim(layout) <- c(field_rows, field_cols)
    return(layout)
  }

  dl <- design$dlist
  if (is.null(dl) || !all(c("ROW", "RANGE", "ID") %in% names(dl))) return(NULL)
  layout <- matrix(NA_real_, nrow = field_rows, ncol = field_cols)
  layout[cbind(as.integer(dl$ROW), as.integer(dl$RANGE))] <- as.numeric(dl$ID)
  layout
}

#' Generate the spatial design for one location using corDiGGer
#'
#' @param params list — scenario inputs
#' @param derived list — output of compute_scenario()
#' @param location integer — 1-based location number
#' @param digger_fn function|NULL — TEST SEAM. NULL means call
#'   DiGGer::corDiGGer(). Injecting a design function lets the property tests
#'   exercise the reshaping logic with a stub on a machine that has no DiGGer
#'   install; it is never used by the App itself.
#' @return list(field_book = data.frame(Block, Plot, Row, Col, Entry),
#'              layout = matrix (field_rows x field_cols of entry IDs),
#'              trt_name = integer vector,
#'              error = character|NULL)
#' @details There is deliberately NO fallback layout. A non-DiGGer layout has no
#'   spatial optimisation and no block-composition guarantee, yet it would
#'   download as an ordinary CSV and could be planted unnoticed. Failing loudly
#'   with the download URL is the only honest behaviour (Req 18.8).
randomize_location <- function(params, derived, location, digger_fn = NULL) {
  fail <- function(msg) {
    list(field_book = NULL, layout = NULL, trt_name = NULL, error = msg)
  }

  # Step 1: hard DiGGer check. No fallback layout — see @details above.
  if (is.null(digger_fn) && !check_digger_available()) {
    return(fail(sprintf(
      paste0("The DiGGer package is not installed, so no design can be generated. ",
             "Install DiGGer from %s and try again."),
      DIGGER_URL)))
  }

  cross_entries <- as_whole_count(params$cross_entries)
  prep_per_loc  <- as_whole_count(params$prep_per_loc)
  check_entries <- as_whole_count(params$check_entries)
  blocks        <- as_whole_count(params$blocks)
  field_rows    <- as_whole_count(params$field_rows)
  field_cols    <- as_whole_count(params$field_cols)
  block_rows    <- as_whole_count(params$block_rows)
  block_cols    <- as_whole_count(params$block_cols)
  pure_test     <- as_whole_count(derived$pure_test)
  common        <- as_whole_count(derived$common_per_loc)
  field_plots   <- as_whole_count(derived$field_plots)
  block_plots   <- as_whole_count(derived$block_plots)

  counts <- c(cross_entries = cross_entries, prep_per_loc = prep_per_loc,
              check_entries = check_entries, blocks = blocks,
              field_rows = field_rows, field_cols = field_cols,
              block_rows = block_rows, block_cols = block_cols,
              pure_test = pure_test, common_per_loc = common,
              field_plots = field_plots, block_plots = block_plots)
  if (anyNA(counts)) {
    return(fail(sprintf(
      "Cannot randomize location %s: %s must be whole numbers before a design can be generated.",
      format_scenario_number(scenario_num(location)),
      paste(names(counts)[is.na(counts)], collapse = ", "))))
  }

  # Steps 2-5: IDs, treatment count, replication vector, treatment names.
  ids <- location_entry_ids(params, derived, location)
  entries  <- common + cross_entries + check_entries
  trt_rep  <- rep(c(1L, blocks, 1L, blocks),
                  c(cross_entries, prep_per_loc, pure_test, check_entries))
  trt_name <- c(ids$cross, ids$prep, ids$unrep, ids$check)

  # Step 6: sanity-check BEFORE handing anything to the optimiser, so a
  # bookkeeping slip reports itself here instead of failing obscurely inside
  # corDiGGer.
  if (length(trt_name) != entries) {
    return(fail(sprintf(
      paste0("Cannot randomize location %s: the treatment name vector holds %s IDs ",
             "but the design needs %s treatments."),
      format_scenario_number(scenario_num(location)),
      format_scenario_number(length(trt_name)), format_scenario_number(entries))))
  }
  if (sum(trt_rep) != as_whole_count(derived$required_plots)) {
    return(fail(sprintf(
      paste0("Cannot randomize location %s: the replication vector accounts for %s plots ",
             "but required plots per location is %s."),
      format_scenario_number(scenario_num(location)),
      format_scenario_number(sum(trt_rep)),
      format_scenario_number(derived$required_plots))))
  }
  if (sum(trt_rep) != field_plots) {
    return(fail(sprintf(
      paste0("Cannot randomize location %s: the replication vector accounts for %s plots ",
             "but the field holds %s (%s x %s)."),
      format_scenario_number(scenario_num(location)),
      format_scenario_number(sum(trt_rep)), format_scenario_number(field_plots),
      format_scenario_number(field_rows), format_scenario_number(field_cols))))
  }
  if (blocks * block_plots != field_plots) {
    return(fail(sprintf(
      paste0("Cannot randomize location %s: %s blocks of %s plots make %s plots ",
             "but the field holds %s."),
      format_scenario_number(scenario_num(location)),
      format_scenario_number(blocks), format_scenario_number(block_plots),
      format_scenario_number(blocks * block_plots),
      format_scenario_number(field_plots))))
  }

  # Step 7: the design call, wrapped so a solver failure becomes a message.
  design_fn <- if (is.null(digger_fn)) {
    function(...) DiGGer::corDiGGer(...)
  } else {
    digger_fn
  }

  design <- tryCatch(
    design_fn(numberOfTreatments = entries,
              rowsInDesign       = field_rows,
              columnsInDesign    = field_cols,
              blockSequence      = list(c(block_rows, block_cols)),
              treatName          = trt_name,
              treatRepPerRep     = trt_rep),
    error = function(e) e
  )
  if (inherits(design, "error") || inherits(design, "condition")) {
    return(fail(sprintf("corDiGGer failed for location %s: %s",
                        format_scenario_number(scenario_num(location)),
                        conditionMessage(design))))
  }

  # Step 8: layout extraction with the code-to-name remap.
  layout <- design_layout_matrix(design, trt_name, entries, field_rows, field_cols)

  # Steps 9-12: the field book.
  dl <- design$dlist
  if (is.null(dl) || !all(c("UNIT", "ROW", "RANGE", "ID") %in% names(dl))) {
    return(fail(sprintf(
      "corDiGGer returned no plot list for location %s, so no field book could be built.",
      format_scenario_number(scenario_num(location)))))
  }

  fb <- dl[, c("UNIT", "ROW", "RANGE", "ID")]
  colnames(fb) <- c("Plot", "Row", "Col", "Entry")
  if (nrow(fb) != field_plots) {
    return(fail(sprintf(
      "corDiGGer returned %s plots for location %s but the field holds %s.",
      format_scenario_number(nrow(fb)),
      format_scenario_number(scenario_num(location)),
      format_scenario_number(field_plots))))
  }

  fb$Block <- rep(seq_len(blocks), each = block_plots)
  fb$Plot  <- with(fb, block_rows * (Col - 1) + Row +
                       (1 - Col %% 2) * (block_rows + 1 - 2 * Row))
  fb <- fb[order(fb$Plot), c("Block", "Plot", "Row", "Col", "Entry")]
  rownames(fb) <- NULL

  list(field_book = fb, layout = layout, trt_name = trt_name, error = NULL)
}

#' Generate the spatial design for every location
#'
#' @param params list — scenario inputs
#' @param derived list — output of compute_scenario()
#' @param progress_callback function(current, total)|NULL — called after each
#'   location so the caller can emit "Processing location X of Y" (Req 23.2)
#' @param digger_fn function|NULL — TEST SEAM, passed straight through to
#'   randomize_location()
#' @return list(field_books = named list, layouts = named list,
#'              trt_names = named list, errors = named list)
#' @details Every element is named "Loc_1", "Loc_2", ... so downstream code never
#'   relies on position. A failure at one location records its message under
#'   errors[["Loc_i"]] and the loop continues with the remaining locations
#'   (Req 18.9). A missing DiGGer is one global failure, reported once under
#'   errors[["DiGGer"]] rather than N identical times (Req 18.8).
randomize_all_locations <- function(params, derived, progress_callback = NULL,
                                    digger_fn = NULL) {
  n_loc <- as_whole_count(params$locations)
  if (is.na(n_loc) || n_loc < 1L) n_loc <- 0L

  field_books <- list()
  layouts     <- list()
  trt_names   <- list()
  errors      <- list()

  if (is.null(digger_fn) && !check_digger_available()) {
    errors[["DiGGer"]] <- sprintf(
      paste0("The DiGGer package is not installed, so no design can be generated for any ",
             "location. Install DiGGer from %s and try again."),
      DIGGER_URL)
    return(list(field_books = field_books, layouts = layouts,
                trt_names = trt_names, errors = errors))
  }

  for (i in seq_len(n_loc)) {
    key <- paste0("Loc_", i)
    res <- tryCatch(
      randomize_location(params, derived, i, digger_fn = digger_fn),
      error = function(e) list(field_book = NULL, layout = NULL, trt_name = NULL,
                               error = sprintf("Unexpected error at location %d: %s",
                                               i, conditionMessage(e)))
    )

    if (!is.null(res$error)) {
      errors[[key]] <- res$error
    } else {
      field_books[[key]] <- res$field_book
      layouts[[key]]     <- res$layout
      trt_names[[key]]   <- res$trt_name
    }

    if (is.function(progress_callback)) progress_callback(i, n_loc)
  }

  list(field_books = field_books, layouts = layouts,
       trt_names = trt_names, errors = errors)
}

# -----------------------------------------------------------------------------
# 8. DiGGer Script Generator
# -----------------------------------------------------------------------------

#' Render the DiGGer R script for one location
#'
#' @param params list — scenario inputs
#' @param derived list — output of compute_scenario()
#' @param location integer — 1-based location number
#' @return character — the complete script as ONE string with embedded newlines
#' @details Pure text substitution: integers are computed and pasted in, never
#'   deparsed from a call object, so the panel shows exactly what the user can
#'   paste into RStudio (Req 17.1-17.10).
#'
#'   The six trt.name endpoints and the four desPlot colour ranges all come from
#'   range() of location_entry_ids() — the same call randomize_location() makes.
#'   Sharing the ID source is what makes Requirement 17.11 structural rather
#'   than merely tested.
#'
#'   Two byte-level details are load-bearing: the trailing space after
#'   "treatName = trt.name," reproduces the workbook output byte for byte, and
#'   block_rows + 1 is substituted as a pre-computed integer rather than emitted
#'   as the expression block.rows+1.
#'
#'   DEGENERATE SEGMENTS: cross_entries and prep_per_loc may legitimately be
#'   zero, and pure_test is zero whenever every common entry is replicated. An
#'   empty segment has no first and last ID, so "lo:hi" cannot be written. Rather
#'   than emit an invalid NA:NA the segment is written as NULL — valid inside
#'   c(), where it contributes nothing — a comment line above trt.name names
#'   every omitted segment, and the matching desPlot call is replaced by a
#'   comment line. The emitted script therefore always parses.
generate_digger_script <- function(params, derived, location) {
  fmt <- format_scenario_number
  ids <- location_entry_ids(params, derived, location)

  cross_entries <- scenario_num(params$cross_entries)
  prep_per_loc  <- scenario_num(params$prep_per_loc)
  check_entries <- scenario_num(params$check_entries)
  blocks        <- scenario_num(params$blocks)
  field_rows    <- scenario_num(params$field_rows)
  field_cols    <- scenario_num(params$field_cols)
  block_rows    <- scenario_num(params$block_rows)
  block_cols    <- scenario_num(params$block_cols)
  pure_test     <- derived$pure_test
  block_plots   <- derived$block_plots
  entries       <- derived$common_per_loc + cross_entries + check_entries
  loc           <- fmt(scenario_num(location))

  labels <- c(cross = "Test Entries Cross Locations",
              prep  = "Replicated Test Entries in P-Rep Design",
              unrep = "Unreplicated Test Entries",
              check = "Check Entries")

  # "lo:hi" from the shared ID source, or NULL for a degenerate empty segment.
  seg <- function(key) {
    v <- ids[[key]]
    if (length(v) == 0) return("NULL")
    bounds <- range(v)
    paste0(fmt(bounds[1]), ":", fmt(bounds[2]))
  }

  empty_keys <- names(labels)[vapply(names(labels),
                                     function(k) length(ids[[k]]) == 0,
                                     logical(1))]
  notes <- if (length(empty_keys) > 0) {
    sprintf("# NOTE: the %s segment is empty at this location; NULL is emitted in its place.",
            labels[empty_keys])
  } else {
    character(0)
  }

  des_plot <- function(key, colour, new) {
    if (length(ids[[key]]) == 0) {
      return(sprintf("# desPlot for %s omitted: the segment is empty at this location.",
                     labels[[key]]))
    }
    sprintf("desPlot(layout, c(%s), col = '%s', new = %s)", seg(key), colour, new)
  }

  lines <- c(
    paste0("# ", DIGGER_URL),
    "library(DiGGer)",
    "",
    paste0("entries <- ", fmt(entries)),
    paste0("field.rows <- ", fmt(field_rows)),
    paste0("field.cols <- ", fmt(field_cols)),
    paste0("block.rows <- ", fmt(block_rows)),
    paste0("block.cols <- ", fmt(block_cols)),
    paste0("trt.rep <- rep(c(1, ", fmt(blocks), ", 1, ", fmt(blocks), "), c(",
           fmt(cross_entries), ", ", fmt(prep_per_loc), ", ",
           fmt(pure_test), ", ", fmt(check_entries), "))"),
    notes,
    paste0("trt.name <- c(", seg("cross"), ", ", seg("prep"), ", ",
           seg("unrep"), ", ", seg("check"), ")"),
    "",
    "design <- corDiGGer(numberOfTreatments = entries,",
    "                    rowsInDesign = field.rows,",
    "                    columnsInDesign = field.cols,",
    "                    blockSequence = list(c(block.rows, block.cols)),",
    "                    treatName = trt.name, ",
    "                    treatRepPerRep = trt.rep)",
    "",
    "layout <- getDesign(design)",
    "layout <- sapply(layout, function(x) trt.name[match(x, 1:entries)])",
    "dim(layout) <- c(field.rows, field.cols)",
    "",
    paste0("png('layout-loc", loc, ".png', width = ", fmt(PNG_WIDTH),
           ", height = ", fmt(PNG_HEIGHT), ", res = ", fmt(PNG_RES), ")"),
    des_plot("cross", ENTRY_TYPE_COLOURS[["Cross"]],        "TRUE"),
    des_plot("prep",  ENTRY_TYPE_COLOURS[["P-Rep"]],        "FALSE"),
    des_plot("unrep", ENTRY_TYPE_COLOURS[["Unreplicated"]], "FALSE"),
    des_plot("check", ENTRY_TYPE_COLOURS[["Check"]],        "FALSE"),
    "desPlot(layout, bdef = cbind(block.rows, block.cols), bwd = 4, bcol = 1, new = FALSE)",
    "dev.off()",
    "",
    "fieldbook <- design$dlist[,c(\"UNIT\", \"ROW\", \"RANGE\", \"ID\")]",
    "colnames(fieldbook) <- c(\"Plot\", \"Row\", \"Col\", \"Entry\")",
    paste0("fieldbook$Block <- rep(1:", fmt(blocks), ", each=", fmt(block_plots), ")"),
    paste0("fieldbook$Plot <- with(fieldbook, ", fmt(block_rows),
           "*(Col-1) + Row + (1-Col%%2)*(", fmt(block_rows + 1), "-2*Row))"),
    "fieldbook <- fieldbook[order(fieldbook$Plot), c(\"Block\", \"Plot\", \"Row\", \"Col\", \"Entry\")]",
    "",
    paste0("write.csv(fieldbook, 'fieldbook-loc", loc, ".csv', row.names = FALSE)")
  )

  paste(lines, collapse = "\n")
}

# -----------------------------------------------------------------------------
# 9. Layout Rendering and Export
# -----------------------------------------------------------------------------

#' Classify entry IDs into entry types by ID membership
#'
#' @param entry numeric vector — Entry values taken from a field book
#' @param ids list — output of location_entry_ids()
#' @return factor with levels Cross, P-Rep, Unreplicated, Check, NA for any ID
#'   outside all four segments
#' @details Resolution is by ID membership, never by a string column: a field
#'   book carries numeric entry IDs and nothing else (Req 18.4), so the entry
#'   type has to be recovered from the ID ranges of that location.
#'
#'   The levels are fixed in the order Cross, P-Rep, Unreplicated, Check and are
#'   never dropped, so the layout legend keeps one stable order regardless of
#'   which types happen to appear in a given field book. The level names match
#'   names(ENTRY_TYPE_COLOURS) exactly, which is what lets scale_fill_manual()
#'   map them without a lookup table.
classify_entry_type <- function(entry, ids) {
  levels_fixed <- c("Cross", "P-Rep", "Unreplicated", "Check")

  e <- suppressWarnings(as.numeric(entry))
  out <- rep(NA_character_, length(e))

  segments <- list(Cross = ids$cross, `P-Rep` = ids$prep,
                   Unreplicated = ids$unrep, Check = ids$check)

  for (type in names(segments)) {
    seg <- segments[[type]]
    if (length(seg) == 0) next
    out[!is.na(e) & e %in% seg] <- type
  }

  factor(out, levels = levels_fixed)
}

#' Render one location's field layout
#'
#' @param field_book data.frame(Block, Plot, Row, Col, Entry) — may be NULL
#' @param ids list — output of location_entry_ids()
#' @param params list — scenario inputs, supplies the field and block dimensions
#' @param derived list — output of compute_scenario(), supplies field_plots
#' @param location integer — location number, used in the title
#' @return ggplot object
#' @details The on-screen equivalent of the generated script's desPlot block:
#'   one tile per plot filled with the entry-type colour (Req 19.1, 19.2), block
#'   boundary lines at every block_rows / block_cols interval standing in for
#'   desPlot(bdef = ..., bwd = 4, bcol = 1) (Req 19.3), and a legend naming the
#'   four entry types (Req 19.4).
#'
#'   scale_y_reverse() puts row 1 at the top, matching desPlot's orientation. A
#'   layout drawn upside down against the printed script is worse than no layout
#'   at all, because it looks plausible.
#'
#'   Entry labels appear only while field_plots stays at or below
#'   LABEL_PLOT_LIMIT, and their size shrinks as the grid grows, so labels never
#'   degrade into unreadable overlap (Req 19.1).
#'
#'   A NULL or empty field book is the normal state before randomization runs,
#'   not an error: it renders as a blank annotated panel so the Results tab has
#'   something to show (Req 19.6).
render_layout_plot <- function(field_book, ids, params, derived, location) {
  loc_label <- format_scenario_number(scenario_num(location))

  blank_plot <- function(message) {
    ggplot2::ggplot() +
      ggplot2::annotate("text", x = 0, y = 0, label = message, size = 5) +
      ggplot2::theme_void()
  }

  if (is.null(field_book) || !is.data.frame(field_book) || nrow(field_book) == 0 ||
      !all(c("Row", "Col", "Entry") %in% names(field_book))) {
    return(blank_plot(sprintf(
      "No layout is available for location %s yet. Generate a design first.", loc_label)))
  }

  plot_data <- field_book
  plot_data$Entry_Type <- classify_entry_type(plot_data$Entry, ids)

  # Field dimensions come from the inputs, falling back to the field book itself
  # so the boundary lines still land correctly if a dimension is unset.
  dim_or_max <- function(value, observed) {
    v <- as_whole_count(value)
    if (is.na(v) || v < 1L) max(1L, as.integer(max(observed, na.rm = TRUE))) else v
  }
  field_rows <- dim_or_max(params$field_rows, plot_data$Row)
  field_cols <- dim_or_max(params$field_cols, plot_data$Col)
  block_rows <- as_whole_count(params$block_rows)
  block_cols <- as_whole_count(params$block_cols)

  p <- ggplot2::ggplot(plot_data) +
    ggplot2::geom_tile(
      ggplot2::aes(x = .data$Col, y = .data$Row, fill = .data$Entry_Type),
      colour = "white") +
    ggplot2::scale_fill_manual(values = ENTRY_TYPE_COLOURS, drop = FALSE,
                               name = "Entry Type", na.value = "grey85")

  # Block boundaries: the ggplot equivalent of desPlot's bdef/bwd/bcol call.
  if (!is.na(block_cols) && block_cols >= 1L) {
    p <- p + ggplot2::geom_vline(
      xintercept = seq(0, field_cols, by = block_cols) + 0.5,
      linewidth = 1.2, colour = "black")
  }
  if (!is.na(block_rows) && block_rows >= 1L) {
    p <- p + ggplot2::geom_hline(
      yintercept = seq(0, field_rows, by = block_rows) + 0.5,
      linewidth = 1.2, colour = "black")
  }

  field_plots <- scenario_num(derived$field_plots)
  if (is.finite(field_plots) && field_plots <= LABEL_PLOT_LIMIT) {
    label_size <- max(1.4, min(4, 80 / max(field_rows, field_cols)))
    p <- p + ggplot2::geom_text(
      ggplot2::aes(x = .data$Col, y = .data$Row, label = .data$Entry),
      size = label_size)
  }

  p +
    ggplot2::scale_y_reverse(breaks = seq_len(field_rows)) +
    ggplot2::scale_x_continuous(breaks = seq_len(field_cols), position = "top") +
    ggplot2::coord_equal(expand = FALSE) +
    ggplot2::labs(
      title = sprintf("Field layout - Location %s", loc_label),
      x = "Column", y = "Row") +
    ggplot2::theme_minimal() +
    ggplot2::theme(
      panel.grid = ggplot2::element_blank(),
      axis.text  = ggplot2::element_text(size = 7)
    )
}

#' Parse the integer location number out of a "Loc_N" key
#'
#' @param key character — e.g. "Loc_3"
#' @param fallback integer — value returned when the key does not parse
#' @return integer
location_from_key <- function(key, fallback = NA_integer_) {
  n <- suppressWarnings(as.integer(sub("^Loc_", "", as.character(key))))
  if (length(n) != 1 || is.na(n)) return(as.integer(fallback))
  n
}

#' Combine per-location field books into one data frame
#'
#' @param randomization list — output of randomize_all_locations()
#' @return data.frame(Location, Block, Plot, Row, Col, Entry) ordered by Location
#'   then Plot; a zero-row frame with those columns when nothing can be combined
#' @details Location holds the integer location number parsed out of the "Loc_N"
#'   key rather than the key itself, so the downloaded CSV sorts numerically and
#'   joins cleanly against the entry code map (Req 21.3).
build_combined_field_book <- function(randomization) {
  cols <- c("Location", "Block", "Plot", "Row", "Col", "Entry")
  empty <- data.frame(
    Location = integer(0), Block = numeric(0), Plot = numeric(0),
    Row = numeric(0), Col = numeric(0), Entry = numeric(0)
  )

  books <- if (is.null(randomization)) NULL else randomization$field_books
  if (is.null(books) || length(books) == 0) return(empty)

  keys <- names(books)
  if (is.null(keys)) keys <- paste0("Loc_", seq_along(books))

  parts <- list()
  for (i in seq_along(books)) {
    fb <- books[[i]]
    if (is.null(fb) || !is.data.frame(fb) || nrow(fb) == 0) next
    if (!all(c("Block", "Plot", "Row", "Col", "Entry") %in% names(fb))) next
    parts[[length(parts) + 1L]] <- data.frame(
      Location = rep(location_from_key(keys[i], i), nrow(fb)),
      Block = fb$Block, Plot = fb$Plot, Row = fb$Row, Col = fb$Col, Entry = fb$Entry
    )
  }

  if (length(parts) == 0) return(empty)

  out <- do.call(rbind, parts)
  out <- out[order(out$Location, out$Plot), cols, drop = FALSE]
  rownames(out) <- NULL
  out
}

#' Build an Excel workbook with one sheet per location (entry codes resolved)
#'
#' @param randomization list — output of randomize_all_locations()
#' @param entry_code_map data.frame|NULL — output of allocation_code_map() with
#'   columns Location, Entry_Type, Entry_ID, Code, …
#' @return An openxlsx Workbook object, or NULL if no valid locations exist
#' @details Each worksheet is named "Location_N" where N is the integer location
#'   number extracted from the "Loc_N" key. Worksheets appear in ascending order
#'   of N. The Entry column is resolved from numeric Entry_ID to the
#'   human-readable Code string using entry_code_map; if no match is found for a
#'   given entry at a location (including the "All" entries), the numeric ID is
#'   used as a character string fallback. The Location column is omitted because
#'   the location is encoded in the worksheet name (Req 4.3).
build_combined_field_book_xlsx <- function(randomization, entry_code_map) {
  books <- if (is.null(randomization)) NULL else randomization$field_books
  if (is.null(books) || length(books) == 0) return(NULL)

  wb <- openxlsx::createWorkbook()

  keys <- names(books)
  if (is.null(keys)) keys <- paste0("Loc_", seq_along(books))

  # Sort keys by numeric location number
  loc_nums <- vapply(keys, function(k) location_from_key(k, NA_integer_), integer(1))
  sorted_order <- order(loc_nums)

  sheets_added <- 0L


  for (idx in sorted_order) {
    key <- keys[idx]
    fb <- books[[key]]

    # Skip if NULL, not a data frame, or zero-row
    if (is.null(fb) || !is.data.frame(fb) || nrow(fb) == 0) next
    # Skip if missing required columns
    if (!all(c("Block", "Plot", "Row", "Col", "Entry") %in% names(fb))) next

    loc_num <- location_from_key(key, idx)

    # Build entry code lookup vector for this location
    code_lookup <- character(0)
    if (!is.null(entry_code_map) && is.data.frame(entry_code_map) &&
        nrow(entry_code_map) > 0 &&
        all(c("Location", "Entry_ID", "Code") %in% names(entry_code_map))) {
      rows <- entry_code_map$Location == as.character(loc_num) |
              entry_code_map$Location == "All"
      subset_map <- entry_code_map[rows, , drop = FALSE]
      if (nrow(subset_map) > 0) {
        code_lookup <- stats::setNames(
          as.character(subset_map$Code),
          as.character(subset_map$Entry_ID)
        )
      }
    }

    # Resolve Entry_ID to Code (fallback to as.character(Entry_ID))
    resolved_entries <- vapply(fb$Entry, function(entry) {
      key_str <- as.character(entry)
      matched <- code_lookup[key_str]
      if (!is.na(matched) && length(matched) == 1) matched else key_str
    }, character(1), USE.NAMES = FALSE)

    # Construct output data frame
    out_df <- data.frame(
      Block = fb$Block,
      Plot  = fb$Plot,
      Row   = fb$Row,
      Col   = fb$Col,
      Entry = resolved_entries,
      stringsAsFactors = FALSE
    )

    # Add worksheet and write data
    sheet_name <- paste0("Location_", loc_num)
    openxlsx::addWorksheet(wb, sheet_name)
    openxlsx::writeData(wb, sheet_name, out_df)
    sheets_added <- sheets_added + 1L
  }

  if (sheets_added == 0L) return(NULL)
  wb
}

#' Write every location layout into one ZIP archive
#'
#' @param randomization list — output of randomize_all_locations()
#' @param params list — scenario inputs
#' @param derived list — output of compute_scenario()
#' @param zip_path character — target path for the archive
#' @return character — zip_path, or NULL when there was nothing to write
#' @details One PNG per successfully randomized location, named
#'   layout-loc{L}.png to match the filenames the generated script writes, at
#'   PNG_WIDTH x PNG_HEIGHT and PNG_RES (Req 21.5, 21.6). The pixel geometry is
#'   converted to inches at PNG_RES, because ggsave() sizes in physical units:
#'   2400/96 = 25in by 1200/96 = 12.5in reproduces the script's device exactly.
#'
#'   Members are stored FLAT, with no directory prefix, so unzipping drops the
#'   PNGs straight into the working directory. That is achieved by running
#'   utils::zip() from inside the staging directory with bare filenames, and
#'   restoring the previous working directory through on.exit() — including when
#'   zipping fails.
#'
#'   The zip status is checked rather than assumed: utils::zip() shells out to an
#'   external zip binary that need not exist, and it reports failure through its
#'   return status. An unchecked failure would hand the user a truncated or
#'   absent file that still downloads as a .zip, so a non-zero status removes the
#'   partial archive and raises a descriptive error naming the status.
build_layout_archive <- function(randomization, params, derived, zip_path) {
  books <- if (is.null(randomization)) NULL else randomization$field_books
  if (is.null(books) || length(books) == 0) return(NULL)

  keys <- names(books)
  if (is.null(keys)) keys <- paste0("Loc_", seq_along(books))

  stage <- tempfile("layout-archive-")
  dir.create(stage, recursive = TRUE, showWarnings = FALSE)

  width_in  <- PNG_WIDTH  / PNG_RES
  height_in <- PNG_HEIGHT / PNG_RES

  members <- character(0)
  for (i in seq_along(books)) {
    fb <- books[[i]]
    if (is.null(fb) || !is.data.frame(fb) || nrow(fb) == 0) next

    loc <- location_from_key(keys[i], i)
    ids <- location_entry_ids(params, derived, loc)
    plot_obj <- render_layout_plot(fb, ids, params, derived, loc)

    member <- sprintf("layout-loc%d.png", loc)
    ggplot2::ggsave(
      filename = file.path(stage, member), plot = plot_obj,
      width = width_in, height = height_in, dpi = PNG_RES,
      units = "in", device = "png", limitsize = FALSE
    )
    members <- c(members, member)
  }

  if (length(members) == 0) return(NULL)

  # Absolute target path: the zip call runs from inside the staging directory,
  # where a relative zip_path would land in the temp tree.
  zip_target <- file.path(
    normalizePath(dirname(zip_path), winslash = "/", mustWork = FALSE),
    basename(zip_path))

  old_wd <- setwd(stage)
  on.exit(setwd(old_wd), add = TRUE)

  status <- tryCatch(
    utils::zip(zipfile = zip_target, files = members, flags = "-q9X"),
    error = function(e) e
  )

  if (inherits(status, "condition")) {
    if (file.exists(zip_target)) unlink(zip_target)
    stop(sprintf(
      paste0("Could not build the layout archive: %s. A zip program must be available ",
             "on the system PATH (or in R_ZIPCMD) to package the layouts."),
      conditionMessage(status)), call. = FALSE)
  }
  if (!identical(as.integer(status), 0L) || !file.exists(zip_target)) {
    if (file.exists(zip_target)) unlink(zip_target)
    stop(sprintf(
      paste0("Could not build the layout archive: the zip program exited with status %s. ",
             "A zip program must be available on the system PATH (or in R_ZIPCMD)."),
      as.character(status)), call. = FALSE)
  }

  zip_path
}

# -----------------------------------------------------------------------------
# 10. UI Module Functions
# -----------------------------------------------------------------------------
#
# Three pure UI constructors. Each returns a shiny tag object and performs no
# computation, so the whole layer can be rendered to HTML in a test without a
# running server.
#
# The Scenario Panel order is itself a requirement (Req 3.1, 7.5, 9, 10): the
# entries upload has to come first because it supplies Test_Entries, and
# "Required plots per location" has to sit immediately before the seed input so
# the user sees the plot budget verdict before committing a seed rate.

# A 200 MB pedigree matrix has to survive the upload, so the Shiny request cap
# is raised from its 5 MB default before any UI is built (Req 5.1).
options(shiny.maxRequestSize = MAX_PEDIGREE_FILE_SIZE_MB * 1024^2)

#' Small muted guidance paragraph
#'
#' @param ... inline content
#' @return shiny.tag
ui_hint <- function(...) {
  tags$p(class = "ui-hint", ...)
}

#' One caption/value pair for a derived figure
#'
#' @param label character — the verbatim Scenario Builder caption (Req 6.8)
#' @param output_id character — namespaced output id carrying the value
#' @return shiny.tag
#' @details The caption is emitted statically rather than being built inside the
#'   server render, so the exact workbook wording is guaranteed to be present in
#'   the rendered page and cannot drift with a server-side code path.
ui_derived_row <- function(label, output_id) {
  tags$div(
    class = "derived-row",
    tags$span(class = "derived-label", label),
    tags$span(class = "derived-value", textOutput(output_id, inline = TRUE))
  )
}

