#' Scenario configuration panel UI
#'
#' @param id character — module namespace id
#' @return shiny.tag.list
#' @details Emits the fifteen control groups in the order the design fixes
#'   (Req 3.1, 3.2, 3.3, 3.5, 6.1, 6.8, 7.1, 7.2, 7.5, 9.1, 9.2, 10.1, 10.3).
#'   Every numeric input carries its own inline error placeholder so a message
#'   can appear adjacent to the offending control rather than in a shared block.
scenario_panel_ui <- function(id) {
  ns <- NS(id)

  tagList(

    # -- 1. Entries CSV upload -------------------------------------------------
    # First control in the panel because it supplies Test_Entries (Req 3.1).
    tags$div(
      class = "panel-block",
      tags$h4("1. Entries file"),
      fileInput(ns("entries_file"), "Upload Entries File (CSV)", accept = ".csv"),
      ui_hint("Three columns are mandatory:"),
      tags$ul(
        class = "ui-hint",
        tags$li(tags$strong("Code"), " \u2014 the unique entry identifier."),
        tags$li(tags$strong("SELHIS"), " \u2014 the selection history, hyphen-separated."),
        tags$li(tags$strong("Available"), " \u2014 the available seed quantity in grams, a positive number.")
      ),
      ui_hint("Example data row:"),
      tags$div(
        class = "ui-example",
        "FFM2600001, ICB23-0484-9765SBR-9718SBR-16392SBR, 142"
      ),
      uiOutput(ns("entries_summary")),
      uiOutput(ns("entries_messages"))
    ),

    # -- 2. Pedigree matrix upload --------------------------------------------
    tags$div(
      class = "panel-block",
      tags$h4("2. Pedigree matrix"),
      fileInput(
        ns("pedigree_file"),
        sprintf("Upload Pedigree Matrix (CSV or gzip-compressed CSV, up to %d MB)",
                MAX_PEDIGREE_FILE_SIZE_MB),
        accept = c(".csv", ".gz", ".csv.gz")
      ),
      ui_hint(paste(
        "A square, symmetric matrix of pedigree similarity coefficients.",
        "The first column holds the row names and the first row the column names,",
        "both being entry Code values."
      )),
      uiOutput(ns("pedigree_summary")),
      uiOutput(ns("pedigree_messages"))
    ),

    # -- 3. Read-only Test entries --------------------------------------------
    # Derived, never editable (Req 3.6). Styled as a dashed read-only box so it
    # cannot be mistaken for one of the numeric inputs below it.
    tags$div(
      class = "readonly-box",
      tags$div(
        class = "derived-row",
        tags$span(class = "derived-label", SCENARIO_LABELS[["test_entries"]]),
        tags$span(class = "derived-value",
                  uiOutput(ns("test_entries_display"), inline = TRUE))
      ),
      ui_hint(paste(
        "Read-only. Taken from the number of data rows in the uploaded entries",
        "file, so it cannot be typed in here."
      ))
    ),

    # -- 4-8. Scenario counts -------------------------------------------------
    tags$div(
      class = "panel-block",
      tags$h4("3. Trial scenario"),

      numericInput(ns("locations"), SCENARIO_LABELS[["locations"]],
                   value = 7, min = PARAM_MINIMUMS$locations, step = 1),
      uiOutput(ns("error_locations")),

      numericInput(ns("check_entries"), SCENARIO_LABELS[["check_entries"]],
                   value = 8, min = PARAM_MINIMUMS$check_entries, step = 1),
      uiOutput(ns("error_check_entries")),

      numericInput(ns("cross_entries"), SCENARIO_LABELS[["cross_entries"]],
                   value = 51, min = PARAM_MINIMUMS$cross_entries, step = 1),
      uiOutput(ns("error_cross_entries")),

      numericInput(ns("prep_per_loc"), SCENARIO_LABELS[["prep_per_loc"]],
                   value = 54, min = PARAM_MINIMUMS$prep_per_loc, step = 1),
      uiOutput(ns("error_prep_per_loc")),

      numericInput(ns("blocks"), SCENARIO_LABELS[["blocks"]],
                   value = 2, min = PARAM_MINIMUMS$blocks, step = 1),
      uiOutput(ns("error_blocks"))
    ),

    # -- 9-10. Field and block dimensions -------------------------------------
    tags$div(
      class = "panel-block",
      tags$h4("4. Field Layout"),
      tags$div(
        class = "ui-note",
        "All locations share identical field and block dimensions."
      ),
      fluidRow(
        column(6, numericInput(ns("field_rows"), "Field Rows",
                               value = 20, min = PARAM_MINIMUMS$field_rows, step = 1)),
        column(6, numericInput(ns("field_cols"), "Field Columns",
                               value = 20, min = PARAM_MINIMUMS$field_cols, step = 1))
      ),
      uiOutput(ns("error_field_rows")),
      uiOutput(ns("error_field_cols")),
      fluidRow(
        column(6, numericInput(ns("block_rows"), "Block Rows",
                               value = 20, min = PARAM_MINIMUMS$block_rows, step = 1)),
        column(6, numericInput(ns("block_cols"), "Block Columns",
                               value = 10, min = PARAM_MINIMUMS$block_cols, step = 1))
      ),
      uiOutput(ns("error_block_rows")),
      uiOutput(ns("error_block_cols"))
    ),

    # -- 11. Derived values ---------------------------------------------------
    # Captions are the verbatim Scenario Builder labels (Req 6.8). They are
    # static; only the numbers come from the server.
    tags$div(
      class = "panel-block",
      tags$h4("5. Derived values"),
      ui_derived_row(SCENARIO_LABELS[["common_per_loc"]],     ns("derived_common_per_loc")),
      ui_derived_row(SCENARIO_LABELS[["unrep_per_loc"]],      ns("derived_unrep_per_loc")),
      ui_derived_row(SCENARIO_LABELS[["pure_test"]],          ns("derived_pure_test")),
      ui_derived_row(SCENARIO_LABELS[["replication_ratio"]],  ns("derived_replication_ratio")),
      ui_derived_row(SCENARIO_LABELS[["connectivity_ratio"]], ns("derived_connectivity_ratio")),
      ui_derived_row(SCENARIO_LABELS[["field_plots"]],        ns("derived_field_plots")),
      ui_derived_row(SCENARIO_LABELS[["block_plots"]],        ns("derived_block_plots")),
      # Block size summary line plus the ratio threshold messages (Req 6.9, 13).
      uiOutput(ns("derived_values"))
    ),

    # -- 12. Required plots per location and the gate status ------------------
    # Sits immediately before the seed input (Req 7.5).
    tags$div(
      class = "panel-block",
      tags$h4("6. Plot budget"),
      ui_derived_row(SCENARIO_LABELS[["required_plots"]], ns("derived_required_plots")),
      tags$div(class = "gate-block", uiOutput(ns("required_plots_status")))
    ),

    # -- 13. Seed grams per plot ----------------------------------------------
    # value = NULL so the control starts empty (Req 10.1).
    tags$div(
      class = "panel-block",
      tags$h4("7. Seed and check names"),
      numericInput(ns("seed_per_plot"), "Seed grams per plot",
                   value = NULL, min = PARAM_MINIMUMS$seed_per_plot, step = 0.1),
      ui_hint(paste(
        "Starts empty. Once a valid entries file is uploaded it is pre-filled",
        "with the smallest Available value in that file; type over it to override."
      )),
      uiOutput(ns("error_seed_per_plot")),

      # -- 14. Check entry names ----------------------------------------------
      textInput(ns("check_names"), "Check entry names (optional)",
                value = "", placeholder = "Cham1, Cham3, Douma1"),
      ui_hint(paste(
        "A comma-separated list, one name per check entry.",
        "Leave it blank and the checks are named check1 through checkN."
      )),
      uiOutput(ns("check_names_message"))
    ),

    # -- 15. Actions ----------------------------------------------------------
    tags$div(
      class = "panel-block",
      tags$h4("8. Run"),
      actionButton(ns("allocate_btn"), "Allocate Entries", class = "btn-success"),
      tags$span(" "),
      actionButton(ns("generate_btn"), "Generate Design", class = "btn-primary"),
      tags$div(
        class = "ui-warn",
        tags$strong("Generate Design is slow by design."), " ",
        paste(
          "The spatial optimisation takes several minutes per location \u2014 around",
          "4 minutes on a typical machine \u2014 so a 7-location run needs roughly",
          "half an hour. The progress message names the location being processed.",
          "The app has not hung; leave it running."
        )
      ),
      uiOutput(ns("action_blockers"))
    )
  )
}

#' Results panel UI (five sub-tabs)
#'
#' @param id character — module namespace id
#' @return shiny.tag — a tabsetPanel
#' @details Sub-tab order is fixed: Diagnostics Summary, Plot Budget & Entry ID
#'   Ranges, Field Layout, DiGGer Script, Downloads
#'   (Req 11.1, 12.1, 19.5, 19.6, 20.1, 20.2, 20.4, 21.1-21.5, 21.7).
results_panel_ui <- function(id) {
  ns <- NS(id)

  tabsetPanel(
    id = ns("results_tabs"),

    # -- 1. Diagnostics Summary ----------------------------------------------
    tabPanel(
      "Diagnostics Summary",
      tags$div(
        class = "panel-block",
        uiOutput(ns("overall_status")),
        ui_hint(paste(
          "One row per location: entry counts by type, the realized replication",
          "and connectivity ratios, and the number of unique families."
        )),
        DT::dataTableOutput(ns("diagnostics_table")),
        uiOutput(ns("diagnostics_messages"))
      )
    ),

    # -- 2. Plot Budget & Entry ID Ranges ------------------------------------
    tabPanel(
      "Plot Budget & Entry ID Ranges",
      tags$div(
        class = "panel-block",
        tags$h4("Plot budget per location"),
        ui_hint(paste(
          "The Plots column must sum to Required plots per location.",
          "Any other total means the design would not fill the field."
        )),
        DT::dataTableOutput(ns("budget_table")),
        uiOutput(ns("budget_total"))
      ),
      tags$div(
        class = "panel-block",
        tags$h4("Entry ID ranges"),
        ui_hint(paste(
          "One row per entry type, one column per location.",
          "Use it to trace any Entry value in a field book back to its type and location."
        )),
        DT::dataTableOutput(ns("id_ranges_table"))
      )
    ),

    # -- 3. Field Layout -----------------------------------------------------
    tabPanel(
      "Field Layout",
      tags$div(
        class = "panel-block",
        selectInput(ns("layout_location"), "Location", choices = NULL),
        plotOutput(ns("field_layout"), height = "650px"),
        uiOutput(ns("layout_legend")),
        uiOutput(ns("layout_message"))
      )
    ),

    # -- 4. DiGGer Script ----------------------------------------------------
    tabPanel(
      "DiGGer Script",
      tags$div(
        class = "panel-block script-box",
        tags$div(
          class = "ui-note",
          paste(
            "This is the script the app ran for the selected location.",
            "It can be pasted into RStudio and run unchanged to reproduce the",
            "same layout and field book."
          )
        ),
        selectInput(ns("script_location"), "Location", choices = NULL),
        # Clipboard access needs JavaScript, so shinyjs is loaded once in the
        # main UI and the copy handler is defined inline here. If the browser
        # refuses clipboard access the button says so and the user can still
        # select the block and copy manually (Req 20.4).
        tags$script(HTML(paste0(
          "function sparsePrepCopyScript(targetId, btn) {\n",
          "  var el = document.getElementById(targetId);\n",
          "  if (!el) { return; }\n",
          "  var text = el.innerText || el.textContent || '';\n",
          "  var done = function (ok) {\n",
          "    var original = btn.getAttribute('data-label') || btn.innerHTML;\n",
          "    btn.setAttribute('data-label', original);\n",
          "    btn.innerHTML = ok ? 'Copied' : 'Copy failed \\u2014 select the text and copy manually';\n",
          "    setTimeout(function () { btn.innerHTML = original; }, 2500);\n",
          "  };\n",
          "  if (navigator.clipboard && navigator.clipboard.writeText) {\n",
          "    navigator.clipboard.writeText(text).then(function () { done(true); },\n",
          "                                             function () { done(false); });\n",
          "  } else {\n",
          "    done(false);\n",
          "  }\n",
          "}\n"
        ))),
        tags$button(
          id      = ns("copy_script_btn"),
          type    = "button",
          class   = "btn btn-default btn-sm",
          onclick = sprintf("sparsePrepCopyScript('%s', this)", ns("digger_script")),
          "Copy script to clipboard"
        ),
        ui_hint(paste(
          "If the browser blocks clipboard access, click inside the block,",
          "select all of it and copy it manually."
        )),
        verbatimTextOutput(ns("digger_script"))
      )
    ),

    # -- 5. Downloads --------------------------------------------------------
    tabPanel(
      "Downloads",
      tags$div(
        class = "panel-block",
        uiOutput(ns("downloads_message")),

        tags$div(
          class = "download-group",
          tags$h5("All locations"),
          ui_hint("One file covering every location in the trial."),
          downloadButton(ns("download_entry_code_map"), "Entry Code Map CSV"),
          tags$span(" "),
          downloadButton(ns("download_combined_field_book"), "Combined Field Book Excel"),
          tags$span(" "),
          downloadButton(ns("download_layout_archive"), "All Layouts (ZIP)")
        ),

        tags$hr(),

        tags$div(
          class = "download-group",
          tags$h5("Single location \u2014 field book"),
          ui_hint("Pick the location, then download that location's field book."),
          selectInput(ns("download_location"), "Location", choices = NULL),
          downloadButton(ns("download_field_book"), "Field Book CSV")
        ),

        tags$div(
          class = "download-group",
          tags$h5("Single location \u2014 layout image"),
          ui_hint("Pick the location, then download that location's layout as a PNG."),
          selectInput(ns("download_layout_location"), "Location", choices = NULL),
          downloadButton(ns("download_layout_png"), "Layout PNG")
        )
      )
    )
  )
}

#' About and help panel UI
#'
#' @return shiny.tag — static content, so no namespace and no id argument
#' @details Carries the repository citation, the Design Rules of Thumb, the two
#'   references, the GPL-3.0 statement, the workflow steps, the two input file
#'   formats and the two-column parameter table
#'   (Req 24.1, 24.2, 24.3, 24.4, 24.5, 24.6, 24.7).
about_help_ui <- function() {

  tags$div(
    class = "about-section",

    # -- About ---------------------------------------------------------------
    tags$h3("About"),
    tags$p(paste(
      "Sparse Spatial P-Rep MET Design turns the Excel-R semi-automated workflow",
      "for sparse partially replicated multi-environment trials into a single",
      "self-contained R Shiny application. Scenario arithmetic, pedigree-aware",
      "entry allocation and spatial randomization through the DiGGer package all",
      "happen in one place."
    )),
    tags$p(
      class = "citation",
      paste(
        "M. Sanchez Garcia, Z. Kehel, and K. Al-Shamaa. (2026).",
        "Sparse Spatial P-Rep MET Randomization: An Excel-R Semi-Automated Workflow",
        "for Pedigree-Aware Entry Allocation. GitHub repository."
      ),
      " ",
      tags$a(href = "https://github.com/icarda/sparse_prep_design",
             target = "_blank", rel = "noopener",
             "https://github.com/icarda/sparse_prep_design")
    ),

    # -- Design Rules of Thumb ------------------------------------------------
    tags$h3("Design Rules of Thumb"),
    tags$ul(
      tags$li(paste(
        "Replicated entries should account for at least 15% of the total entries",
        "in each location. The typical replication ratio is 1:4",
