      )),
      tags$li(paste(
        "Shared entries across locations should account for at least 15% of the",
        "total entries in each location. Research on sparse METs indicates that",
        "prediction accuracy and model stability decline significantly when the",
        "proportion of common entries falls below 10%. An overlap of 15-20% is",
        "generally recommended for reliable connectivity in mixed-model or",
        "GP-assisted MET analysis (e.g. Jarquin et al., 2020)."
