# -----------------------------------------------------------------------------
# 11. Server Module Functions
# -----------------------------------------------------------------------------
#
# The module server functions have to be defined ahead of the top-level `server`
# that calls them, so this section sits between the UI module functions and the
# Main UI Assembly, and the assembly section moves to 12 to keep the numbering
# sequential.
#
# Two module servers live here: the Scenario Panel, which owns the uploads and
# the scenario reactive graph, and the Results Panel, which owns the five
# Results sub-tabs. The allocation and randomization orchestrators sit in the
# top-level `server` of section 12, because they bridge the two modules.

#' Render zero or more messages, one styled block each
#'
#' @param texts character — message texts; empty and NA entries are dropped
#' @param class character — CSS class: "ui-error", "ui-warn", "ui-note", "ui-ok"
#' @return shiny.tag.list|NULL — NULL when there is nothing to say, so the
#'   placeholder collapses instead of leaving an empty box behind
srv_messages <- function(texts, class) {
  if (length(texts) == 0) return(NULL)
  texts <- texts[!is.na(texts) & nzchar(texts)]
  if (length(texts) == 0) return(NULL)
  tagList(lapply(texts, function(txt) tags$div(class = class, txt)))
}

#' Enable or disable one control by its bare (un-namespaced) input id
#'
#' @param id character — the input id WITHOUT the module namespace prefix
#' @param condition logical — TRUE enables, FALSE disables
#' @details shinyjs 2.1.0 namespaces the `id` argument itself whenever the
#'   session is a module `session_proxy` (see shinyjs:::jsFuncHelper), so the
#'   bare id must be passed here. Passing session$ns("allocate_btn") would send
#'   "scenario-scenario-allocate_btn", which matches no element, and the button
#'   would silently stay enabled forever.
#'
#'   The call is guarded because shiny::MockShinySession — the session used by
#'   shiny::testServer — implements no sendCustomMessage, so a headless test of
#'   the module would otherwise die inside the gating observer rather than
#'   exercising the reactive graph.
srv_toggle_state <- function(id, condition) {
  tryCatch(
    shinyjs::toggleState(id = id, condition = isTRUE(condition)),
    error = function(e) invisible(NULL)
  )
}

#' Numeric scenario inputs, their labels and their minimums
#'
#' One entry per numeric control in the Scenario Panel, in panel order. Driving
#' both the inline error placeholders and the button gating from this one list
#' keeps a control from acquiring an error message the gating ignores
#' (Req 25.1-25.4).
#'
#' seed_per_plot is the only continuous input: integer_only = FALSE makes its
#' minimum EXCLUSIVE, which is the "greater than zero" rule of Req 10.4.
SCENARIO_INPUT_SPECS <- list(
  list(id = "locations",     label = SCENARIO_LABELS[["locations"]],
       min = PARAM_MINIMUMS$locations,     integer_only = TRUE),
  list(id = "check_entries", label = SCENARIO_LABELS[["check_entries"]],
       min = PARAM_MINIMUMS$check_entries, integer_only = TRUE),
  list(id = "cross_entries", label = SCENARIO_LABELS[["cross_entries"]],
       min = PARAM_MINIMUMS$cross_entries, integer_only = TRUE),
  list(id = "prep_per_loc",  label = SCENARIO_LABELS[["prep_per_loc"]],
       min = PARAM_MINIMUMS$prep_per_loc,  integer_only = TRUE),
  list(id = "blocks",        label = SCENARIO_LABELS[["blocks"]],
       min = PARAM_MINIMUMS$blocks,        integer_only = TRUE),
  list(id = "field_rows",    label = "Field Rows",
       min = PARAM_MINIMUMS$field_rows,    integer_only = TRUE),
  list(id = "field_cols",    label = "Field Columns",
       min = PARAM_MINIMUMS$field_cols,    integer_only = TRUE),
  list(id = "block_rows",    label = "Block Rows",
       min = PARAM_MINIMUMS$block_rows,    integer_only = TRUE),
  list(id = "block_cols",    label = "Block Columns",
       min = PARAM_MINIMUMS$block_cols,    integer_only = TRUE),
  list(id = "seed_per_plot", label = "Seed grams per plot",
       min = PARAM_MINIMUMS$seed_per_plot, integer_only = FALSE)
)

#' The three plot-budget gates, captioned for the status block
GATE_LABELS <- list(
  G1 = "G1 \u2014 Required plots per location equals Field Plots",
  G2 = "G2 \u2014 Block Rows x Block Columns x Augmented blocks equals Field Plots",
  G3 = "G3 \u2014 (Test entries - Entries cross locations) divides evenly by Locations"
)

#' Read one pedigree upload into a named numeric matrix
#'
#' @param path character — temp path of the uploaded file
#' @param filename character — original file name, used only to detect gzip
#' @return list(matrix = matrix|NULL, error = character)
#' @details The first column becomes the row names and the remaining columns the
#'   values (Req 5.2). `.gz` is detected from the file NAME, case-insensitively,
#'   because the upload temp path carries no extension. check.names = FALSE
#'   keeps entry Codes that start with a digit from being mangled into "X123".
#'
#'   A cell that will not coerce to numeric is reported with the same wording
#'   validate_pedigree() uses, because a matrix carrying NAs would otherwise
#'   reach the symmetry comparison and turn an if() condition into NA.
srv_read_pedigree_matrix <- function(path, filename) {
  raw <- tryCatch({
    if (grepl("\\.gz$", filename, ignore.case = TRUE)) {
      con <- gzfile(path, "rt")
      on.exit(close(con), add = TRUE)
      utils::read.csv(con, stringsAsFactors = FALSE, check.names = FALSE)
    } else {
      utils::read.csv(path, stringsAsFactors = FALSE, check.names = FALSE)
    }
  }, error = function(e) e)

  if (inherits(raw, "error")) {
    return(list(matrix = NULL, error = sprintf(
      "Could not read the pedigree file: %s", conditionMessage(raw))))
  }
  if (ncol(raw) < 2 || nrow(raw) < 1) {
    return(list(matrix = NULL, error = paste(
      "The pedigree file needs an entry code column followed by one column per",
      "entry; this file has fewer than two columns."
    )))
  }

  m <- as.matrix(raw[, -1, drop = FALSE])
  rownames(m) <- as.character(raw[[1]])
  colnames(m) <- names(raw)[-1]
  coerced <- suppressWarnings({ storage.mode(m) <- "numeric"; m })

  if (any(is.na(coerced))) {
    return(list(matrix = NULL, error = "Pedigree matrix contains non-numeric values"))
  }
  list(matrix = coerced, error = character(0))
}

#' Scenario panel server logic
#'
#' @param id character — module namespace id, matching scenario_panel_ui()
#' @return list(params = reactive, derived = reactive, gates = reactive,
#'              check_names = reactive, entries = reactive, pedigree = reactive,
#'              allocate = reactive, generate = reactive,
#'              ready = list(allocate = reactive, generate = reactive))
#' @details Owns the two uploads, the whole scenario reactive graph and every
#'   status message in the panel. The reactives it returns are the single source
#'   the allocation and randomization orchestrators consume, so no downstream
#'   module recomputes the arithmetic (Req 6.11, 7.5, 8.4, 8.5, 9.4, 9.5, 10.4,
#'   13.1-13.4, 25.1-25.7).
scenario_panel_server <- function(id) {
  moduleServer(id, function(input, output, session) {

    # -------------------------------------------------------------------------
    # Upload state. Held in reactiveVals rather than reactives because a file
    # upload is an event: the value has to survive until the NEXT upload, and a
    # failed upload has to clear the previous one so no stale entries frame can
    # keep the Allocate button alive.
    # -------------------------------------------------------------------------
    entries_state  <- reactiveVal(NULL)   # list(data, summary)
    entries_errors <- reactiveVal(character(0))
    pedigree_state <- reactiveVal(NULL)   # list(data, summary)
    pedigree_errors   <- reactiveVal(character(0))
    pedigree_warnings <- reactiveVal(character(0))

    # -- Entries upload (Req 3.4, 4.1, 4.3-4.6, 10.2, 23.3) -------------------
    observeEvent(input$entries_file, {
      info <- input$entries_file
      if (is.null(info) || is.null(info$datapath)) return()

      entries_state(NULL)
      entries_errors(character(0))

      result <- withProgress(
        message = "Reading entries file",
        detail  = as.character(info$name[[1]]),
        value   = 0.2,
        {
          raw <- tryCatch(
            utils::read.csv(as.character(info$datapath[[1]]), stringsAsFactors = FALSE),
            error = function(e) e
          )
          incProgress(0.5, detail = "Validating")
          if (inherits(raw, "error")) {
            list(valid = FALSE, data = NULL, summary = NULL,
                 errors = sprintf("Could not read the entries file: %s",
                                  conditionMessage(raw)))
          } else {
            validate_entries(raw)
          }
        }
      )

      if (isTRUE(result$valid)) {
        entries_state(list(data = result$data, summary = result$summary))
        # Pre-fill the seed rate from the user's own data, on upload ONLY
        # (Req 10.2). Doing this on every reactive tick would overwrite whatever
        # the user is typing.
        updateNumericInput(session, "seed_per_plot",
                           value = result$summary$min_available)
      } else {
        entries_errors(result$errors)
      }
    })

    # -- Pedigree upload (Req 5.1, 5.2, 5.4, 5.6, 23.3) -----------------------
    observeEvent(input$pedigree_file, {
      info <- input$pedigree_file
      if (is.null(info) || is.null(info$datapath)) return()

      pedigree_state(NULL)
      pedigree_errors(character(0))
      pedigree_warnings(character(0))

      ent <- entries_state()
      entry_codes <- if (is.null(ent)) character(0) else as.character(ent$data$Code)

      result <- withProgress(
        message = "Reading pedigree matrix",
        detail  = as.character(info$name[[1]]),
        value   = 0.15,
        {
          parsed <- srv_read_pedigree_matrix(
            as.character(info$datapath[[1]]), as.character(info$name[[1]]))
          incProgress(0.6, detail = "Validating")
          if (is.null(parsed$matrix)) {
            list(valid = FALSE, data = NULL, summary = NULL,
                 errors = parsed$error, warnings = character(0))
          } else {
            tryCatch(
              validate_pedigree(parsed$matrix, entry_codes),
              error = function(e) list(
                valid = FALSE, data = NULL, summary = NULL,
                errors = sprintf("Pedigree matrix could not be validated: %s",
                                 conditionMessage(e)),
                warnings = character(0))
            )
          }
        }
      )

      if (isTRUE(result$valid)) {
        pedigree_state(list(data = result$data, summary = result$summary))
        pedigree_warnings(result$warnings)
      } else {
        pedigree_errors(result$errors)
        pedigree_warnings(result$warnings)
      }
    })

    # -- Upload summaries and messages ----------------------------------------
    output$entries_summary <- renderUI({
      ent <- entries_state()
      if (is.null(ent)) return(NULL)
      s <- ent$summary
      tags$div(
        class = "ui-ok",
        sprintf(
          paste("%s entries loaded. Available seed ranges from %s to %s g.",
                "%s unique families."),
          format_scenario_number(s$n),
          format_scenario_number(s$min_available),
          format_scenario_number(s$max_available),
          format_scenario_number(s$n_families)
        )
      )
    })

    output$entries_messages <- renderUI(srv_messages(entries_errors(), "ui-error"))

    output$pedigree_summary <- renderUI({
      ped <- pedigree_state()
      if (is.null(ped)) return(NULL)
      s <- ped$summary
      tagList(
        tags$div(
          class = "ui-ok",
          sprintf("Pedigree matrix loaded: %d \u00d7 %d. %d entr%s matched to the entries file.",
                  s$nrow, s$ncol, s$n_matched,
                  if (s$n_matched == 1) "y" else "ies")
        ),
        srv_messages(pedigree_warnings(), "ui-warn")
      )
    })

    output$pedigree_messages <- renderUI({
      tagList(
        srv_messages(pedigree_errors(), "ui-error"),
        if (length(pedigree_errors()) > 0) srv_messages(pedigree_warnings(), "ui-warn")
      )
    })

    # -------------------------------------------------------------------------
    # The scenario reactive graph. params() is the ONLY place inputs are read
    # into the arithmetic layer, so every derived figure, gate and message below
    # is computed from one consistent snapshot.
    # -------------------------------------------------------------------------
    params <- reactive({
      ent <- entries_state()
      list(
        locations     = input$locations,
        # Test_Entries is the entries row count, never a manual input (Req 3.6).
        # NA while no file is loaded, which is what makes gate G3 report
        # "cannot be evaluated" rather than inventing a number.
        test_entries  = if (is.null(ent)) NA_real_ else nrow(ent$data),
        check_entries = input$check_entries,
        cross_entries = input$cross_entries,
        prep_per_loc  = input$prep_per_loc,
        blocks        = input$blocks,
        field_rows    = input$field_rows,
        field_cols    = input$field_cols,
        block_rows    = input$block_rows,
        block_cols    = input$block_cols,
        seed_per_plot = input$seed_per_plot
      )
    })

    derived     <- reactive(compute_scenario(params()))
    gates       <- reactive(validate_plot_budget(params(), derived()))
    consistency <- reactive(validate_parameter_consistency(params(), derived()))
    check_names <- reactive(parse_check_names(input$check_names, input$check_entries))

    # validate_plot_budget() returns the hard gate errors and the advisory ratio
    # messages in one vector. The gate errors belong in the plot budget status
    # block and the ratio messages in the derived values block, so they are
    # split on the "Gate G" prefix the validator writes.
    gate_errors  <- reactive(grep("^Gate G", gates()$errors, value = TRUE))
    ratio_errors <- reactive(grep("^Gate G", gates()$errors, value = TRUE, invert = TRUE))

    # -------------------------------------------------------------------------
    # Derived value renderers. Counts print through format_scenario_number();
    # the two ratios are proportions in [0, 1] and are shown as percentages to
    # one decimal place (Req 6.6, 6.7). A missing value prints as "-" rather
    # than the literal "NA".
    # -------------------------------------------------------------------------
    render_count <- function(value_fn) {
      renderText({
        v <- value_fn()
        if (length(v) != 1 || !is.finite(v)) "-" else format_scenario_number(v)
      })
    }

    render_percent <- function(value_fn) {
      renderText({
        v <- value_fn()
        if (length(v) != 1 || !is.finite(v)) "-" else sprintf("%.1f%%", v * 100)
      })
    }

    output$derived_common_per_loc <- render_count(function() derived()$common_per_loc)
    output$derived_unrep_per_loc  <- render_count(function() derived()$unrep_per_loc)
    output$derived_pure_test      <- render_count(function() derived()$pure_test)
    output$derived_field_plots    <- render_count(function() derived()$field_plots)
    output$derived_block_plots    <- render_count(function() derived()$block_plots)
    output$derived_required_plots <- render_count(function() derived()$required_plots)

    output$derived_replication_ratio  <- render_percent(function() derived()$replication_ratio)
    output$derived_connectivity_ratio <- render_percent(function() derived()$connectivity_ratio)

    # Read-only Test entries. Explicit prompt while no file is loaded (Req 3.5).
    output$test_entries_display <- renderUI({
      ent <- entries_state()
      if (is.null(ent)) {
        tags$span(style = "color:#a94442;", "Upload an entries file")
      } else {
        tags$span(format_scenario_number(nrow(ent$data)))
      }
    })

    # Block size summary plus the ratio threshold messages (Req 6.9, 13.1-13.4).
    output$derived_values <- renderUI({
      d <- derived()
      ratio_ok <- length(ratio_errors()) == 0 && length(gates()$warnings) == 0 &&
        is.finite(d$replication_ratio) && is.finite(d$connectivity_ratio)
      tagList(
        tags$div(class = "ui-note", d$block_size_summary),
        srv_messages(ratio_errors(), "ui-error"),
        srv_messages(gates()$warnings, "ui-warn"),
        if (ratio_ok) {
          tags$div(class = "ui-ok", sprintf(
            "Replication Ratio (%.1f%%) and Connectivity Ratio (%.1f%%) both meet the %d%% minimum.",
            d$replication_ratio * 100, d$connectivity_ratio * 100,
            THRESHOLD_REPLICATION_WARNING))
        }
      )
    })

    # Per-gate badge plus the full text of every failing gate. This block is the
    # answer to "why is Generate Design disabled?" (Req 8.1-8.5).
    output$required_plots_status <- renderUI({
      g <- gates()
      errs <- gate_errors()

      badges <- lapply(names(GATE_LABELS), function(key) {
        passed <- isTRUE(g$gates[[key]])
        tagList(
          tags$div(
            class = if (passed) "gate-pass" else "gate-fail",
            paste0(if (passed) "PASS \u2014 " else "FAIL \u2014 ", GATE_LABELS[[key]])
          ),
          srv_messages(grep(paste0("^Gate ", key), errs, value = TRUE), "ui-error")
        )
      })

      tagList(
        badges,
        if (isTRUE(g$valid)) {
          tags$div(class = "ui-ok", paste(
            "Plot budget passes: all three gates hold, so Generate Design is",
            "available once entries and pedigree are loaded."
          ))
        } else {
          tags$div(class = "ui-error", paste(
            "Generate Design stays disabled while any gate above is failing."
          ))
        }
      )
    })

    # -------------------------------------------------------------------------
    # Inline input validation (Req 25.1-25.6). One named character vector, ""
    # meaning acceptable, so the placeholders and the button gating read the
    # same verdict.
    # -------------------------------------------------------------------------
    input_errors <- reactive({
      ids  <- vapply(SCENARIO_INPUT_SPECS, function(spec) spec$id, character(1))
      msgs <- vapply(SCENARIO_INPUT_SPECS, function(spec) {
        validate_numeric_input(input[[spec$id]], spec$min, spec$label, spec$integer_only)
      }, character(1))
      stats::setNames(msgs, ids)
    })

    # The two cross-parameter errors are attached to the control the user has to
    # change: the cross-entries error next to Entries cross locations (Req 25.5),
    # the P-Rep error next to P-Rep test entries per location (Req 25.6).
    consistency_for <- function(input_id) {
      errs <- consistency()$errors
      if (length(errs) == 0) return(character(0))
      switch(input_id,
        cross_entries = grep("cannot exceed Test entries", errs, value = TRUE),
        prep_per_loc  = grep("^P-Rep test entries per location", errs, value = TRUE),
        character(0)
      )
    }

    for (spec in SCENARIO_INPUT_SPECS) {
      local({
        this <- spec
        output[[paste0("error_", this$id)]] <- renderUI({
          srv_messages(c(input_errors()[[this$id]], consistency_for(this$id)), "ui-error")
        })
      })
    }

    # -- Check entry names (Req 9.4, 9.5) -------------------------------------
    output$check_names_message <- renderUI({
      parsed <- check_names()
      n_conf <- scenario_num(input$check_entries)
      if (isTRUE(parsed$used_fallback)) {
        tags$div(class = "ui-note", sprintf(
          "No check names entered; the checks will be named check1 through check%s.",
          format_scenario_number(n_conf)
        ))
      } else if (isTRUE(parsed$count_mismatch)) {
        tags$div(class = "ui-warn", sprintf(
          "%d check name%s parsed but Check entries is %s; the two counts differ.",
          length(parsed$names), if (length(parsed$names) == 1) " was" else "s were",
          format_scenario_number(n_conf)
        ))
      } else {
        tags$div(class = "ui-ok", sprintf(
          "%d check name%s parsed: %s.",
          length(parsed$names), if (length(parsed$names) == 1) "" else "s",
          paste(parsed$names, collapse = ", ")
        ))
      }
    })

    # -------------------------------------------------------------------------
    # Action gating. blockers() names, in plain words, everything currently
    # standing between the user and a run. It is rendered next to the buttons,
    # which is the tooltip equivalent Req 25.7 asks for: a disabled button in a
    # browser swallows its own tooltip, so the list is shown instead of hidden
    # behind a hover.
    # -------------------------------------------------------------------------
    blockers <- reactive({
      out <- character(0)

      if (is.null(entries_state())) {
        out <- c(out, "No entries file loaded \u2014 upload the entries CSV.")
      }
      if (is.null(pedigree_state())) {
        out <- c(out, "No pedigree matrix loaded \u2014 upload the pedigree CSV or CSV.GZ.")
      }

      errs <- input_errors()
      out <- c(out, unname(errs[nzchar(errs)]))
      out <- c(out, consistency()$errors)

      g <- gates()
      failing <- names(GATE_LABELS)[!vapply(names(GATE_LABELS),
                                            function(k) isTRUE(g$gates[[k]]), logical(1))]
      if (length(failing) > 0) {
        out <- c(out, sprintf("Plot budget gate %s is failing (Generate Design only).",
                              paste(failing, collapse = ", ")))
      }
      out
    })

    # Allocate needs data and clean inputs; the plot budget gates constrain the
    # randomization, not the allocation (Req 25.7).
    allocate_ready <- reactive({
      !is.null(entries_state()) &&
        !is.null(pedigree_state()) &&
        !any(nzchar(input_errors())) &&
        length(consistency()$errors) == 0
    })

    # Generate additionally needs all three gates (Req 8.4, 8.5). Task 11.4 adds
    # the completed-allocation condition once the allocation reactive exists.
    generate_ready <- reactive(allocate_ready() && isTRUE(gates()$valid))

    output$action_blockers <- renderUI({
      items <- blockers()
      allocation_note <- paste(
        "Generate Design also needs a completed allocation \u2014 run Allocate",
        "Entries first."
      )
      if (length(items) == 0) {
        tagList(
          tags$div(class = "ui-ok", "Allocate Entries is ready to run."),
          tags$div(class = "ui-note", allocation_note)
        )
      } else {
        tagList(
          tags$div(class = "ui-error", "The action buttons are disabled because:"),
          tags$ul(class = "ui-hint", lapply(items, tags$li)),
          tags$div(class = "ui-note", allocation_note)
        )
      }
    })

    observe({
      srv_toggle_state("allocate_btn", allocate_ready())
      srv_toggle_state("generate_btn", generate_ready())
    })

    # -------------------------------------------------------------------------
    # Everything the rest of the app consumes. The two button reactives are
    # returned so the orchestrators of tasks 11.3 and 11.4 can trigger on a
    # click without reaching into this module's namespace.
    # -------------------------------------------------------------------------
    list(
      params      = params,
      derived     = derived,
      gates       = gates,
      check_names = check_names,
      entries     = reactive(entries_state()$data),
      pedigree    = reactive(pedigree_state()$data),
      allocate    = reactive(input$allocate_btn),
      generate    = reactive(input$generate_btn),
      ready       = list(allocate = allocate_ready, generate = generate_ready)
    )
  })
}

#' Format an elapsed duration for a progress message
#'
#' @param seconds numeric — elapsed seconds
#' @return character — "48 s", "4 min 12 s" or "1 h 06 min"
#' @details A 7-location run takes roughly half an hour, so the elapsed time is
#'   the only signal that separates "still working" from "hung" (Req 23.2). A
#'   bare second count stops being readable past a few minutes, hence the units.
srv_format_elapsed <- function(seconds) {
  s <- suppressWarnings(as.numeric(seconds))
  if (length(s) != 1 || !is.finite(s) || s < 0) return("0 s")
  s <- round(s)
  if (s < 60) return(sprintf("%d s", s))
  if (s < 3600) return(sprintf("%d min %02d s", s %/% 60, s %% 60))
  sprintf("%d h %02d min", s %/% 3600, (s %% 3600) %/% 60)
}

#' Named location choices for a location selector
#'
#' @param n integer — number of locations
#' @return named character/numeric vector — labels "Location 1".., values 1..n
#' @details The names are the labels and the values the bare numbers, so the
#'   dropdown reads "Location 3" while input$layout_location is "3"
#'   (Req 19.5, 20.2).
srv_location_choices <- function(n) {
  if (length(n) != 1 || is.na(n) || n < 1) return(character(0))
  stats::setNames(seq_len(n), paste("Location", seq_len(n)))
}

#' Read a location selector back as a positive integer
#'
#' @param value character|numeric|NULL — the raw input value
#' @param fallback integer — value used while the selector is still empty
#' @return integer
#' @details selectInput hands values back as character, and every selector is
#'   empty until the first updateSelectInput() lands, so the DiGGer Script panel
#'   would have no location to render before the first flush. Defaulting to
#'   location 1 is what lets the script render immediately (Req 20.5).
srv_selected_location <- function(value, fallback = 1L) {
  v <- as_whole_count(value)
  if (is.na(v) || v < 1L) as.integer(fallback) else v
}

#' Colour swatch legend for the four entry types
#'
#' @return shiny.tag
#' @details Duplicates the ggplot legend deliberately: the plot legend lives
#'   inside a bitmap that a screen reader cannot read, while these swatches are
#'   real DOM elements carrying the entry-type names as text (Req 19.4).
srv_entry_type_legend <- function() {
  swatches <- lapply(names(ENTRY_TYPE_COLOURS), function(type) {
    tags$span(
      style = "display:inline-flex; align-items:center; gap:6px; margin-right:16px;",
      tags$span(
        style = sprintf(
          paste0("display:inline-block; width:14px; height:14px; ",
                 "background:%s; border:1px solid #999;"),
          ENTRY_TYPE_COLOURS[[type]]),
        `aria-hidden` = "true"
      ),
      tags$span(type)
    )
  })
  tags$div(style = "margin-top:8px; font-size:12px;", swatches)
}

#' Build the per-location diagnostics table from an allocation result
#'
#' @param allocation list|NULL — output of allocate_entries()
#' @param params list — scenario inputs, supplies locations
#' @return data.frame(Location, Check, Cross, "P-Rep", Unreplicated, Total,
#'   "Replication %", "Connectivity %", Families) with the numeric ratios
#'   attached as the attributes "replication" and "connectivity"
#' @details COUNTING RULE: cross-location and check entries carry Location "All"
#'   because they are present at EVERY location, so their full counts enter every
#'   row. Only the P-Rep and unreplicated frames are filtered on Location == L
#'   (Req 22.1).
#'
#'   DENOMINATOR: the realized ratios use the same denominator as
#'   compute_scenario()'s B13/B14, namely check + prep + unrep_per_loc, where
#'   B9's unrep_per_loc counts the pure unreplicated entries PLUS the
#'   cross-location entries. The realized equivalent is therefore
#'   check + prep + unreplicated_at_L + cross, which is exactly the Total column.
#'   Anyone reconciling this table against the Scenario Panel can read Total as
#'   the shared denominator of both ratios.
#'
#'     replication  = (Check + P-Rep) / Total          [B13]
#'     connectivity = (Check + Cross) / Total          [B14]
#'
#'   The ratio cells carry a warning marker naming the violated threshold
#'   whenever they fall below 15% (Req 22.4, 22.5); the numeric ratios travel as
#'   attributes so the overall status can count violations without re-parsing the
#'   formatted percentages.
#'
#'   FAMILIES: the distinct non-NA Family values among the entries present at
#'   that location (Req 22.3). Check entries are named strings with no pedigree,
#'   so their Family is NA and they contribute nothing.
srv_diagnostics_table <- function(allocation, params) {
  empty <- data.frame(
    Location = integer(0), Check = integer(0), Cross = integer(0),
    `P-Rep` = integer(0), Unreplicated = integer(0), Total = integer(0),
    `Replication %` = character(0), `Connectivity %` = character(0),
    Families = integer(0), check.names = FALSE, stringsAsFactors = FALSE
  )
  if (is.null(allocation)) return(empty)

  n_loc <- as_whole_count(params$locations)
  if (is.na(n_loc) || n_loc < 1L) return(empty)

  n_rows <- function(df) if (is.null(df) || !is.data.frame(df)) 0L else nrow(df)
  loc_rows <- function(df, loc) {
    if (n_rows(df) == 0L || !"Location" %in% names(df)) return(integer(0))
    which(suppressWarnings(as.numeric(df$Location)) == loc)
  }
  families_of <- function(df, rows = NULL) {
    if (n_rows(df) == 0L || !"Family" %in% names(df)) return(character(0))
    v <- if (is.null(rows)) df$Family else df$Family[rows]
    v <- as.character(v)
    v[!is.na(v) & nzchar(v)]
  }

  cross <- allocation$cross_location
  prep  <- allocation$p_rep
  unrep <- allocation$unreplicated
  chk   <- allocation$check

  n_cross <- n_rows(cross)
  n_check <- n_rows(chk)
  cross_families <- families_of(cross)
  check_families <- families_of(chk)

  mark <- function(ratio, threshold) {
    if (!is.finite(ratio)) return("-")
    txt <- sprintf("%.1f%%", ratio * 100)
    if (ratio * 100 < threshold) {
      paste0(txt, " \u26a0 below the ", threshold, "% minimum")
    } else {
      txt
    }
  }

  rep_ratios <- numeric(n_loc)
  con_ratios <- numeric(n_loc)

  rows <- lapply(seq_len(n_loc), function(loc) {
    prep_idx  <- loc_rows(prep, loc)
    unrep_idx <- loc_rows(unrep, loc)
    n_prep  <- length(prep_idx)
    n_unrep <- length(unrep_idx)
    total   <- n_check + n_cross + n_prep + n_unrep

    replication  <- if (total > 0) (n_check + n_prep)  / total else NA_real_
    connectivity <- if (total > 0) (n_check + n_cross) / total else NA_real_
    rep_ratios[loc] <<- replication
    con_ratios[loc] <<- connectivity

    families <- unique(c(cross_families, check_families,
                         families_of(prep, prep_idx),
                         families_of(unrep, unrep_idx)))

    data.frame(
      Location = loc, Check = n_check, Cross = n_cross,
      `P-Rep` = n_prep, Unreplicated = n_unrep, Total = total,
      `Replication %`  = mark(replication,  THRESHOLD_REPLICATION_WARNING),
      `Connectivity %` = mark(connectivity, THRESHOLD_CONNECTIVITY_WARNING),
      Families = length(families),
      check.names = FALSE, stringsAsFactors = FALSE
    )
  })

  out <- do.call(rbind, rows)
  attr(out, "replication")  <- rep_ratios
  attr(out, "connectivity") <- con_ratios
  out
}

#' Results panel server logic
#'
#' @param id character — module namespace id, matching results_panel_ui()
#' @param params reactive — scenario inputs
#' @param derived reactive — compute_scenario() output
#' @param allocation reactive — allocate_entries() output, NULL before the first
#'   Allocate Entries click
#' @param randomization reactive — randomize_all_locations() output, NULL before
#'   the first Generate Design click
#' @return invisible NULL — the module only renders
#' @details Everything here has to render BEFORE allocation and randomization
#'   have run: the plot budget, the entry ID ranges and the DiGGer script are
#'   pure functions of the scenario inputs (Req 11, 12, 20.5), and the layout and
#'   downloads panels owe the user an explanation rather than an empty box
#'   (Req 19.6, 21.7).
#'
#'   The two orchestrator reactives are eventReactives, so reading either one
#'   before its button has ever been clicked raises the silent "no event yet"
#'   condition instead of returning NULL. Both are therefore read through the
#'   tryCatch wrappers below, which turn that condition into NULL while keeping
#'   the reactive dependency intact.
results_panel_server <- function(id, params, derived, allocation, randomization) {
  moduleServer(id, function(input, output, session) {

    alloc_safe <- reactive(tryCatch(allocation(),    error = function(e) NULL))
    rand_safe  <- reactive(tryCatch(randomization(), error = function(e) NULL))

    # An allocation that failed carries its errors instead of usable frames.
    alloc_ok <- reactive({
      a <- alloc_safe()
      !is.null(a) && length(a$errors) == 0
    })
    rand_ok <- reactive({
      r <- rand_safe()
      !is.null(r) && length(r$field_books) > 0
    })

    archive_error <- reactiveVal(character(0))

    # -------------------------------------------------------------------------
    # The four location selectors, refilled whenever Locations changes (Task
    # 11.4). Each keeps its current selection when that location still exists,
    # so raising Locations from 5 to 7 does not silently jump the user back to
    # location 1 (Req 19.5, 20.2).
    # -------------------------------------------------------------------------
    LOCATION_SELECTORS <- c("layout_location", "script_location",
                            "download_location", "download_layout_location")

    prev_loc_count <- reactiveVal(0L)
    observe({
      n <- as_whole_count(params()$locations)
      if (is.na(n) || n < 1L) return()
      if (identical(n, prev_loc_count())) return()
      prev_loc_count(n)
      choices <- srv_location_choices(n)
      for (control in LOCATION_SELECTORS) {
        current <- srv_selected_location(isolate(input[[control]]), 1L)
        if (current > n) current <- 1L
        updateSelectInput(session, control, choices = choices,
                          selected = as.character(current))
      }
    })

    layout_loc   <- reactive(srv_selected_location(input$layout_location))
    script_loc   <- reactive(srv_selected_location(input$script_location))
    book_loc     <- reactive(srv_selected_location(input$download_location))
    png_loc      <- reactive(srv_selected_location(input$download_layout_location))

    field_book_for <- function(loc) {
      r <- rand_safe()
      if (is.null(r)) return(NULL)
      r$field_books[[paste0("Loc_", loc)]]
    }

    # -------------------------------------------------------------------------
    # 1. Diagnostics Summary (Task 12.1, Req 22.1-22.6)
    # -------------------------------------------------------------------------
    diagnostics <- reactive(srv_diagnostics_table(alloc_safe(), params()))

    # server = FALSE on all three tables: none of them ever exceeds a few dozen
    # rows, so server-side paging buys nothing, and shipping the rows inside the
    # widget payload keeps the rendered table self-contained (it survives a
    # headless testServer() run, where no AJAX round trip can happen).
    output$diagnostics_table <- DT::renderDataTable({
      tbl <- diagnostics()
      DT::datatable(
        tbl, rownames = FALSE, selection = "none",
        options = list(paging = FALSE, searching = FALSE, info = FALSE,
                       ordering = FALSE, dom = "t")
      )
    }, server = FALSE)

    output$overall_status <- renderUI({
      a <- alloc_safe()
      if (is.null(a)) {
        return(tags$div(class = "ui-note", paste(
          "No allocation yet. Run Allocate Entries to populate the diagnostics",
          "for every location."
        )))
      }
      if (!alloc_ok()) {
        return(tags$div(class = "ui-error", paste(
          "Allocation did not complete, so no per-location diagnostics could be",
          "computed. The errors below name the cause."
        )))
      }

      tbl <- diagnostics()
      rep_r <- attr(tbl, "replication")
      con_r <- attr(tbl, "connectivity")
      rep_bad <- sum(!is.finite(rep_r) | rep_r * 100 < THRESHOLD_REPLICATION_WARNING)
      con_bad <- sum(!is.finite(con_r) | con_r * 100 < THRESHOLD_CONNECTIVITY_WARNING)

      if (rep_bad == 0 && con_bad == 0) {
        tags$div(class = "ui-ok", sprintf(
          "All %d locations pass both %d%% thresholds.",
          nrow(tbl), THRESHOLD_REPLICATION_WARNING))
      } else {
        tags$div(class = "ui-warn", sprintf(
          paste("%d of %d locations fall below the %d%% Replication Ratio and",
                "%d of %d fall below the %d%% Connectivity Ratio."),
          rep_bad, nrow(tbl), THRESHOLD_REPLICATION_WARNING,
          con_bad, nrow(tbl), THRESHOLD_CONNECTIVITY_WARNING))
      }
    })

    output$diagnostics_messages <- renderUI({
      a <- alloc_safe()
      if (is.null(a)) return(NULL)
      tagList(
        srv_messages(a$errors,   "ui-error"),
        srv_messages(a$warnings, "ui-warn")
      )
    })

    # -------------------------------------------------------------------------
    # 2. Plot Budget & Entry ID Ranges (Task 11.5, Req 11.1-11.6, 12.1)
    # -------------------------------------------------------------------------
    budget <- reactive(build_plot_budget_table(params(), derived()))

    output$budget_table <- DT::renderDataTable({
      DT::datatable(
        budget(), rownames = FALSE, selection = "none",
        options = list(paging = FALSE, searching = FALSE, info = FALSE,
                       ordering = FALSE, dom = "t")
      )
    }, server = FALSE)

    # The Plots total is only meaningful against Required plots per location, so
    # the verdict is rendered beside it rather than left to the reader (Req 11.6).
    output$budget_total <- renderUI({
      plots_total <- sum(budget()$Plots)
      required    <- scenario_num(derived()$required_plots)

      if (!is.finite(plots_total) || !is.finite(required)) {
        return(tags$div(class = "ui-note", paste(
          "The Plots total cannot be computed yet \u2014 upload an entries file and",
          "complete the scenario inputs."
        )))
      }

      if (isTRUE(all.equal(plots_total, required))) {
        tags$div(class = "ui-ok", sprintf(
          "PASS \u2014 Plots total %s equals Required plots per location (%s).",
          format_scenario_number(plots_total), format_scenario_number(required)))
      } else {
        tags$div(class = "ui-error", sprintf(
          "FAIL \u2014 Plots total %s does not equal Required plots per location (%s); difference %s.",
          format_scenario_number(plots_total), format_scenario_number(required),
          format_scenario_number(plots_total - required)))
      }
    })

    # build_entry_id_ranges() carries the entry-type labels in the ROW NAMES, so
    # rownames must be rendered or the table loses its row identity (Req 12.1).
    output$id_ranges_table <- DT::renderDataTable({
      DT::datatable(
        build_entry_id_ranges(params(), derived()),
        rownames = TRUE, selection = "none",
        options = list(paging = FALSE, searching = FALSE, info = FALSE,
                       ordering = FALSE, dom = "t", scrollX = TRUE)
      )
    }, server = FALSE)

    # -------------------------------------------------------------------------
    # 3. Field Layout (Task 11.5, Req 19.1, 19.4, 19.5, 19.6)
    # -------------------------------------------------------------------------
    output$field_layout <- renderPlot({
      loc <- layout_loc()
      render_layout_plot(
        field_book_for(loc),
        location_entry_ids(params(), derived(), loc),
        params(), derived(), loc
      )
    })

    output$layout_legend <- renderUI(srv_entry_type_legend())

    output$layout_message <- renderUI({
      r <- rand_safe()
      loc <- layout_loc()

      if (is.null(r)) {
        return(tags$div(class = "ui-note", paste(
          "No design has been generated yet, so there is no layout to draw.",
          "Run Allocate Entries, then Generate Design; the layout appears here",
          "once randomization completes."
        )))
      }

      errors <- unlist(r$errors, use.names = FALSE)
      missing_here <- is.null(field_book_for(loc))

      tagList(
        srv_messages(errors, "ui-error"),
        if (missing_here) {
          tags$div(class = "ui-warn", sprintf(
            "Location %d produced no field book, so no layout can be drawn for it.",
            loc))
        } else {
          tags$div(class = "ui-ok", sprintf(
            "Layout shown for location %d. %d of %d locations were randomized.",
            loc, length(r$field_books),
            length(r$field_books) + length(r$errors)))
        }
      )
    })

    # -------------------------------------------------------------------------
    # 4. DiGGer Script (Task 11.5, Req 20.3, 20.5)
    # -------------------------------------------------------------------------
    # Pure text: it depends on params() and derived() only, never on the
    # randomization, so it is available before any design has been generated and
    # regenerates on every scenario input change (Req 20.5).
    output$digger_script <- renderText({
      tryCatch(
        generate_digger_script(params(), derived(), script_loc()),
        error = function(e) sprintf(
          "The script cannot be generated yet: %s", conditionMessage(e))
      )
    })

    # -------------------------------------------------------------------------
    # 5. Downloads (Task 11.6, Req 21.1-21.7)
    # -------------------------------------------------------------------------
    # Every control is gated twice: shinyjs disables the button so it cannot be
    # clicked, and req() in each content function refuses to write a file even if
    # a stale click arrives from a browser that ignored the disabled attribute
    # (Req 21.7).
    DOWNLOAD_CONTROLS <- c("download_entry_code_map", "download_field_book",
                           "download_combined_field_book", "download_layout_png",
                           "download_layout_archive")

    observe({
      enabled <- rand_ok()
      for (control in DOWNLOAD_CONTROLS) srv_toggle_state(control, enabled)
    })

    output$downloads_message <- renderUI({
      r <- rand_safe()

      if (is.null(r)) {
        return(tags$div(class = "ui-note", paste(
          "Downloads become available once design generation completes.",
          "Run Allocate Entries, then Generate Design; every control below stays",
          "disabled until then."
        )))
      }
      if (!rand_ok()) {
        return(tagList(
          tags$div(class = "ui-error", paste(
            "Design generation produced no field book, so there is nothing to",
            "download. The errors below name the cause."
          )),
          srv_messages(unlist(r$errors, use.names = FALSE), "ui-error")
        ))
      }

      tagList(
        tags$div(class = "ui-ok", sprintf(
          "%d location%s randomized \u2014 downloads are available.",
          length(r$field_books), if (length(r$field_books) == 1) "" else "s")),
        srv_messages(unlist(r$errors, use.names = FALSE), "ui-warn"),
        srv_messages(archive_error(), "ui-error")
      )
    })

    output$download_entry_code_map <- downloadHandler(
      filename = function() "Entry_Code_Map.csv",
      contentType = "text/csv",
      content = function(file) {
        a <- alloc_safe()
        req(!is.null(a), rand_ok())
        utils::write.csv(a$entry_code_map, file, row.names = FALSE)
      }
    )

    output$download_field_book <- downloadHandler(
      filename = function() sprintf("fieldbook-loc%d.csv", book_loc()),
      contentType = "text/csv",
      content = function(file) {
        fb <- field_book_for(book_loc())
        req(!is.null(fb))
        utils::write.csv(fb[, c("Block", "Plot", "Row", "Col", "Entry"), drop = FALSE],
                         file, row.names = FALSE)
      }
    )

    output$download_combined_field_book <- downloadHandler(
      filename = function() "fieldbook-all-locations.xlsx",
      contentType = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
      content = function(file) {
        r <- rand_safe()
        a <- alloc_safe()
        req(!is.null(r), rand_ok(), !is.null(a))
        wb <- build_combined_field_book_xlsx(r, a$entry_code_map)
        req(!is.null(wb))
        openxlsx::saveWorkbook(wb, file, overwrite = TRUE)
      }
    )

    output$download_layout_png <- downloadHandler(
      filename = function() sprintf("layout-loc%d.png", png_loc()),
      contentType = "image/png",
      content = function(file) {
        loc <- png_loc()
        fb  <- field_book_for(loc)
        req(!is.null(fb))
        plot_obj <- render_layout_plot(
          fb, location_entry_ids(params(), derived(), loc), params(), derived(), loc)
        # Inches at PNG_RES reproduce the 2400 x 1200 device of the generated
        # script exactly, because ggsave() sizes in physical units (Req 21.4).
        ggplot2::ggsave(
          filename = file, plot = plot_obj,
          width = PNG_WIDTH / PNG_RES, height = PNG_HEIGHT / PNG_RES,
          dpi = PNG_RES, units = "in", device = "png", limitsize = FALSE
        )
      }
    )

    output$download_layout_archive <- downloadHandler(
      filename = function() "layouts-all-locations.zip",
      contentType = "application/zip",
      content = function(file) {
        r <- rand_safe()
        req(!is.null(r), rand_ok())

        # utils::zip() UPDATES an existing archive rather than replacing it, and
        # Shiny may hand over a zero-byte temp file, which zip rejects as a
        # corrupt archive. Removing it first keeps the call on the create path.
        if (file.exists(file) && file.size(file) == 0) unlink(file)

        result <- tryCatch(
          build_layout_archive(r, params(), derived(), file),
          error = function(e) e
        )

        if (inherits(result, "condition")) {
          # build_layout_archive() stop()s when no zip binary is reachable. A
          # download cannot render UI, so the message is pushed as a
          # notification, parked for the downloads panel, and re-raised so the
          # browser gets an error instead of a truncated .zip (Req 25.8).
          msg <- conditionMessage(result)
          archive_error(msg)
          tryCatch(showNotification(msg, type = "error", duration = NULL),
                   error = function(e) invisible(NULL))
          stop(msg, call. = FALSE)
        }
        if (is.null(result)) {
          msg <- "No location produced a layout, so the archive would be empty."
          archive_error(msg)
          stop(msg, call. = FALSE)
        }
        archive_error(character(0))
      }
    )

    invisible(NULL)
  })
}


# -----------------------------------------------------------------------------
# 12. Main UI Assembly
# -----------------------------------------------------------------------------
#
# fluidPage with an explicit header div rather than navbarPage. A Bootstrap 3
# navbar is 50px tall and clips or stretches around a 64px image, and its brand
# element collapses the logo and the title into one anchor. An explicit header
# div puts the 64px logo immediately before an <h2> title with no clipping, and
# a plain tabsetPanel below it gives the same two-tab navigation
# (Req 1.1, 1.2, 2.1, 2.2).

ui <- fluidPage(

  title = "Sparse Spatial P-Rep MET Design",

  shinyjs::useShinyjs(),
  app_css(),

  # Logo immediately before the title text (Req 2.1)
  tags$div(
    class = "app-header",
    icarda_logo_tag(),
    tags$h2("Sparse Spatial P-Rep MET Design")
  ),

  tabsetPanel(
    id = "main_tabs",

    tabPanel(
      "Design",
      sidebarLayout(
        sidebarPanel(
          width = 4,
          scenario_panel_ui("scenario")
        ),
        mainPanel(
          width = 8,
          results_panel_ui("results")
        )
      )
    ),

    tabPanel(
      "About & Help",
      about_help_ui()
    )
  )
)

# Top-level server. The Scenario Panel module owns the uploads, the scenario
# reactive graph and the panel status messages; the Results Panel module owns the
# five Results sub-tabs. The two orchestrators below are the bridge: they turn a
# button click into an allocation or a randomization and hand the result to the
# Results Panel.
server <- function(input, output, session) {

  scenario <- scenario_panel_server("scenario")

  # ---------------------------------------------------------------------------
  # Allocation orchestrator (Task 11.3, Req 14.2, 14.3, 15.3, 23.1, 23.4, 25.7)
  # ---------------------------------------------------------------------------
  # The result is ALSO parked in a reactiveVal so the randomization orchestrator
  # can test "an allocation exists and succeeded" without reading allocation()
  # and thereby re-running a 16-second job on every Generate Design click.
  allocation_value <- reactiveVal(NULL)

  allocation <- eventReactive(scenario$allocate(), {
    req(scenario$ready$allocate())

    # PROGRESS THROTTLE: filter_by_diversity() calls back once per removed
    # entry, which on the 2004-entry dataset is thousands of iterations. An
    # unthrottled setProgress() sends one websocket message per iteration and the
    # reactive flush then costs more than the allocation itself, so an update is
    # emitted only when the whole-percent figure changes or every 25th iteration
    # (Req 23.1).
    tick <- new.env(parent = emptyenv())
    tick$iteration <- 0L
    tick$last_step <- -1L

    progress_callback <- function(current, total) {
      tick$iteration <- tick$iteration + 1L
      fraction <- if (is.finite(total) && total > 0) current / total else 0
      step <- as.integer(floor(fraction * 100))
      if (step == tick$last_step && tick$iteration %% 25L != 0L) {
        return(invisible(NULL))
      }
      tick$last_step <- step
      setProgress(
        value  = 0.05 + 0.9 * min(1, max(0, fraction)),
        detail = sprintf("Diversity filtering: %s of %s",
                         format_scenario_number(current),
                         format_scenario_number(total))
      )
    }

    withProgress(
      message = "Allocating entries",
      detail  = "Filtering on seed availability",
      value   = 0.02,
      tryCatch(
        allocate_entries(
          entries     = scenario$entries(),
          pedigree    = scenario$pedigree(),
          params      = scenario$params(),
          derived     = scenario$derived(),
          check_names = scenario$check_names()$names,
          progress_callback = progress_callback
        ),
        # An unexpected R error must not take the session down: it comes back as
        # an allocation carrying the message, which the Diagnostics Summary
        # renders like any other allocation error (Req 25.8).
        error = function(e) list(
          cross_location = NULL, p_rep = NULL, unreplicated = NULL, check = NULL,
          entry_code_map = allocation_code_map(list()),
          warnings = character(0),
          errors   = sprintf("Entry allocation failed: %s", conditionMessage(e))
        )
      )
    )
  }, ignoreInit = TRUE)

  # eventReactive is lazy, so the click alone computes nothing until a consumer
  # reads it. This observer is that consumer: it forces the run regardless of
  # which Results sub-tab happens to be open, and parks the result. tryCatch
  # swallows the silent req() condition raised when the gating says "not ready".
  observeEvent(scenario$allocate(), {
    result <- tryCatch(allocation(), error = function(e) NULL)
    if (!is.null(result)) allocation_value(result)
  }, ignoreInit = TRUE)

  # ---------------------------------------------------------------------------
  # Randomization orchestrator (Task 11.4, Req 18.1, 18.2, 18.8-18.10, 23.2, 23.4)
  # ---------------------------------------------------------------------------
  randomization <- eventReactive(scenario$generate(), {
    req(scenario$ready$generate())

    # A missing or failed allocation leaves the entry IDs unresolved, so there is
    # nothing to randomize (Req 18.10).
    alloc <- allocation_value()
    req(!is.null(alloc))
    req(length(alloc$errors) == 0)

    # Hard stop with the download URL rather than a fallback layout (Req 18.8).
    if (!check_digger_available()) {
      tryCatch(
        showModal(modalDialog(
          title = "The DiGGer package is not installed",
          tags$p(paste(
            "Spatial randomization is performed by corDiGGer() from the DiGGer",
            "package, which is not installed on this machine. No design can be",
            "generated until it is available."
          )),
          tags$p("Download and install DiGGer from:"),
          tags$p(tags$a(href = DIGGER_URL, target = "_blank",
                        rel = "noopener noreferrer", DIGGER_URL)),
          easyClose = TRUE,
          footer = modalButton("Close")
        )),
        error = function(e) invisible(NULL)
      )
      return(NULL)
    }

    n_loc <- as_whole_count(scenario$params()$locations)
    if (is.na(n_loc) || n_loc < 1L) n_loc <- 0L
    started <- Sys.time()

    progress_callback <- function(current, total) {
      elapsed  <- as.numeric(difftime(Sys.time(), started, units = "secs"))
      next_loc <- min(as.integer(current) + 1L, as.integer(total))
      setProgress(
        value = if (is.finite(total) && total > 0) current / total else 0,
        # Req 23.2 fixes this wording. randomize_all_locations() calls back AFTER
        # a location finishes, so the message names the location now being worked
        # on and the detail reports what is already done.
        message = sprintf("Processing location %d of %d", next_loc, as.integer(total)),
        detail  = sprintf(
          paste("%d of %d locations complete \u2014 elapsed %s.",
                "Each location takes several minutes; the app has not hung."),
          as.integer(current), as.integer(total), srv_format_elapsed(elapsed))
      )
    }

    withProgress(
      message = sprintf("Processing location 1 of %d", n_loc),
      detail  = "Each location takes several minutes; the app has not hung.",
      value   = 0,
      {
        out <- NULL
        # corDiGGer prints a search-progress table to stdout for every phase of
        # every location. Left alone it floods the console and each write
        # competes with the reactive flush, so it is swallowed here. Only stdout
        # is diverted: errors and warnings are conditions, not output, so they
        # still propagate to the tryCatch below.
        invisible(utils::capture.output(
          out <- tryCatch(
            randomize_all_locations(
              params  = scenario$params(),
              derived = scenario$derived(),
              progress_callback = progress_callback
            ),
            error = function(e) list(
              field_books = list(), layouts = list(), trt_names = list(),
              errors = list(Unexpected = sprintf(
                "Design generation failed: %s", conditionMessage(e)))
            )
          ),
          type = "output"
        ))
        out
      }
    )
  }, ignoreInit = TRUE)

  # Same laziness argument as the allocation pump above.
  observeEvent(scenario$generate(), {
    tryCatch(randomization(), error = function(e) NULL)
  }, ignoreInit = TRUE)

  # NOTE on Req 23.4: R evaluates one expression at a time, so while either
  # withProgress() block above holds the session thread no second allocation or
  # randomization can start. The Scenario Panel's own gating observer re-asserts
  # the button states on the next flush.

  results_panel_server(
    id            = "results",
    params        = scenario$params,
    derived       = scenario$derived,
    allocation    = allocation,
    randomization = randomization
  )

}

shinyApp(ui = ui, server = server)
